(window.EX_CHUNKS=window.EX_CHUNKS||{})["b40"]={"过敏":[["他对某种海鲜过敏，吃了就会起皮疹。","ئۇ بىر خىل دېڭىز مەھسۇلاتىغا ئاللېرگىيىسى بار، يېسەلا تېرىسىگە ئىششىق چىقىدۇ.","u bir xil déngiz mehsulatigha allérgiyisi bar, yésela térisige ishshiq chiqidu."]],"卑鄙":[["这种卑鄙的手段令人不齿。","بۇنداق رەزىل ھىيلە-مىكىرلەر كىشىنى يىرگىندۈرىدۇ.","bundaq rezil hiyle-mikirler kishini yirgindüridu."]],"并非":[["这并非他真正的想法。","بۇ ئۇنىڭ ھەقىقىي ئويى ئەمەس.","bu uning heqiqiy oyi emes."]],"卨":[["这块石碑上刻有“卨”字。","بۇ تاش ئابىدە ئۈستىگە «شې» خېتى ئويۇلغان.","bu tash abide üstige «shé» xéti oyulghan."]],"堨":[["堨田里种满了水稻。","دەمبە ئېتىزلىقىغا شال تولۇق تېرىلغان.","dembe étizliqigha shal toluq térilghan."]],"孨":[["孨人生活在深山中。","ئۈچ ئوغۇل تاغنىڭ چوڭقۇرىدا ياشايدۇ.","üch oghul taghning chongqurida yashaydu."]],"岨":[["岨崎的地形给交通带来不便。","تەسىس تىك يەر شەكلى قاتناشقا قولايسىزلىق ئېلىپ كېلىدۇ.","tesis tik yer shekli qatnashqa qolaysizliq élip kélidu."]],"搨":[["他搨了印章在纸上。","ئۇ پېچەتنى قەغەزگە باستى.","u péchetni qeghezge basti."]],"欨":[["他欨地笑了笑。","ئۇ كۈلۈمسىرەپ كۈلۈپ قويدى.","u külümsirep külüp qoydi."]],"渨":[["山间的小溪清澈，没有一丝渨浊。","تاغ ئارىسىدىكى جىلغا سۈيى تۇپتۇزۇق، ھېچقانداق لاي يوق.","tagh arisidiki jilgha süyi tuptuzuq, héchqandaq lay yoq."]],"洨":[["洨水清澈见底。","شياۋ شۇي تۇپتۇز، تېگى كۆرۈنۈپ تۇرىدۇ.","shyaw shuy tuptuz, tégi körünüp turidu."]],"瑨":[["瑨的书法作品令人敬佩。","جىننىڭ خەت-خەتلىك ئەسەرلىرى كىشىنى ھەيران قالدۇرىدۇ.","jinning xet-xetlik eserliri kishini heyran qalduridu."]],"繨":[["绳索被反复繨紧。","ئارغامچا قايتا-قايتا تارتىلىپ چىڭىتىلدى.","arghamcha qayta-qayta tartilip chingitildi."]],"粨":[["这种粨是手工制作的糕点。","بۇ خىل بەي قولدا ياسالغان تاتلىق تائام.","bu xil bey qolda yasalghan tatliq taam."]],"舨":[["舨是一种小型的木船。","بان دېگەن كىچىك تىپتىكى ياغاچ كېمە.","ban dégen kichik tiptiki yaghach kéme."]],"蚨":[["蚨是一种会发出奇特叫声的昆虫。","فۇ بىر خىل غەلىتە ئاۋاز چىقىرىدىغان ھاشارات.","fu bir xil ghelite awaz chiqiridighan hasharat."]],"詨":[["他的詨言令人忍俊不禁。","ئۇنىڭ كۈلكىلىك سۆزى كىشىنى كۈلدۈرۈپ قويىدۇ.","uning külkilik sözi kishini küldürüp qoyidu."]],"邨":[["邨里的人们生活简朴。","كەنتتىكى كىشىلەرنىڭ تۇرمۇشى ئاددىي.","kenttiki kishilerning turmushi addiy."]],"阨":[["这座城阨易守难攻。","بۇ شەھەر ئايىغىنى قوغداش ئاسان، ھۇجۇم قىلىش تەس.","bu sheher ayighini qoghdash asan, hujum qilish tes."]],"鞨":[["鞨鼓的声响在战场上格外响亮。","گە دۇمبىقىنىڭ ئاۋازى جەڭ مەيدانىدا ئالاھىدە ياڭرايتتى.","ge dumbiqining awazi jeng meydanida alahide yangraytti."]],"一穷二白":[["他们刚创业时一穷二白。","ئۇلار ئىش باشلىغان چاغدا ھەممە نەرسىدىن قۇرۇق ئىدى.","ular ish bashlighan chaghda hemme nersidin quruq idi."]],"一线之隔":[["他们之间仅有一线之隔。","ئۇلارنىڭ ئارىسىدا پەقەت بىر تالچىلىق پەرق بار.","ularning arisida peqet bir talchiliq perq bar."]],"一胎制":[["这个国家实行一胎制政策。","بۇ دۆلەت بىر بالىلىق سىياسىتىنى يولغا قويدى.","bu dölet bir baliliq siyasitini yolgha qoydi."]],"一诺千金":[["他说话一诺千金，从不食言。","ئۇنىڭ سۆزى ئىشەنچلىك، ھەرگىز ئېغىزىدىن چىققان سۆزىدە تۇرمايدۇ.","uning sözi ishenchlik, hergiz éghizidin chiqqan sözide turmaydu."]],"一遍又一遍":[["他一遍又一遍地练习着。","ئۇ قايتا-قايتا مەشىق قىلىۋاتىدۇ.","u qayta-qayta meshiq qiliwatidu."]],"三民":[["三民主义是孙中山提出的核心思想。","ئۈچ خەلق پرىنسىپى سۈن جۇڭشەن ئوتتۇرىغا قويغان يادرولۇق ئىدىيەدۇر.","üch xelq prinsipi sün jungshen otturigha qoyghan yadroluq idiyedur."]],"三角测量法":[["工程师用三角测量法计算距离。","ئىنژېنېر ئۈچبۇلۇڭلۇق ئۆلچەش ئۇسۇلى بىلەن مۇساپىنى ھېسابلايدۇ.","inzhénér üchbulungluq ölchesh usuli bilen musapini hésablaydu."]],"不可逆转":[["局势已经变得不可逆转。","ئەھۋال ئاللىبۇرۇن ئۆزگەرتىلگۈسىز ھالەتكە كەلدى.","ehwal alliburun özgertilgüsiz haletke keldi."]],"上确界":[["数学中的上确界有严格定义。","ماتېماتىكىدىكى ئۈستۈنكى چەك قاتتىق ئېنىقلىمىغا ئىگە.","matématikidiki üstünki chek qattiq éniqlimigha ige."]],"丁酉":[["丁酉年运势不错。","دىڭ يۇ يىلىنىڭ تەلەيى ياخشى.","ding yu yilining teleyi yaxshi."]],"不怕":[["我什么都不怕，就怕失败。","مەن ھېچ نەرسىدىن قورقمايمەن، پەقەت مەغلۇبىيەتتىن قورقىمەن.","men héch nersidin qorqmaymen, peqet meghlubiyettin qorqimen."]],"不对头":[["这个计划有点不对头，可能需要修改。","بۇ پىلاندا سەل مەسىلە بار، ئېھتىمال ئۆزگەرتىش كېرەك.","bu pilanda sel mesile bar, éhtimal özgertish kérek."]],"不平等条约":[["历史上许多不平等条约令人愤慨。","تارىختا نۇرغۇن ئادالەتسىز شەرتنامىلەر كىشىنى غەزەپلەندۈرىدۇ.","tarixta nurghun adaletsiz shertnamiler kishini ghezeplendüridu."]],"且听下回分解":[["且听下回分解，继续看故事。","كېيىنكى قىسىمنى ئاڭلاپ، ھېكايىنى داۋاملىق كۆرۈڭ.","kéyinki qisimni anglap, hékayini dawamliq körüng."]],"世代交替":[["王朝的世代交替充满动荡。","سۇلالەنىڭ ئەۋلاد ئالمىشىشى داۋالغۇشلارغا تولغان.","sulalening ewlad almishishi dawalghushlargha tolghan."]],"丢到家":[["这次失败真是丢到家了。","بۇ قېتىمقى مەغلۇبىيەت ھەقىقەتەن ناھايىتى شەرمەندىلىك بولدى.","bu qétimqi meghlubiyet heqiqeten nahayiti shermendilik boldi."]],"丘逢甲":[["丘逢甲是清末的革命家。","چيۇ فېڭجيا چىڭ سۇلالىسىنىڭ ئاخىرقى دەۋرىدىكى ئىنقىلابچى.","chyu féngjya ching sulalisining axirqi dewridiki inqilabchi."]],"中原区":[["中原区是城市的核心区域。","ئوتتۇرا تۈزلەڭلىك رايونى شەھەرنىڭ يادرو رايونى.","ottura tüzlenglik rayoni sheherning yadro rayoni."]],"中央党校":[["中央党校是党员学习的重要场所。","مەركىزىي پارتىيە مەكتىپى پارتىيە ئەزالىرىنىڭ ئۆگىنىشىدىكى مۇھىم ئورۇندۇر.","merkiziy partiye mektipi partiye ezalirining öginishidiki muhim orundur."]],"中段":[["河流的中段较为平缓。","دەريانىڭ ئوتتۇرا بۆلىكى بىر قەدەر تۈزلەڭدۇر.","deryaning ottura böliki bir qeder tüzlengdur."]],"中耳炎":[["他因中耳炎不得不请假休息。","ئۇ ئوتتۇرا قۇلاق ياللۇغى سەۋەبىدىن دەم ئېلىشقا مەجبۇر بولدى.","u ottura qulaq yallughi sewebidin dem élishqa mejbur boldi."]],"串通":[["他串通同事作弊。","ئۇ خىزمەتدىشى بىلەن تىل بىرىكىپ ئالدامچىلىق قىلدى.","u xizmetdishi bilen til birikip aldamchiliq qildi."]],"主球":[["主球在斯诺克比赛中至关重要。","باش توپ سنۇكېر مۇسابىقىسىدە ئىنتايىن مۇھىم.","bash top snukér musabiqiside intayin muhim."]],"中华台北":[["中华台北是台湾的代表。","جۇڭخۇا تەيبېي تەيۋەننىڭ ۋەكىلىدۇر.","jungxua teybéy teywenning wekilidur."]],"乙酰胺吡咯烷酮":[["乙酰胺吡咯烷酮是一种多功能有机化合物。","ئاتسېتامىد پىررولىدىنون كۆپ ئىقتىدارلىق بىر خىل ئورگانىك بىرىكمە.","atsétamid pirrolidinon köp iqtidarliq bir xil organik birikme."]],"乘人之危":[["他乘人之危，趁机占了便宜。","ئۇ باشقىلارنىڭ قىيىنچىلىقىدىن پايدىلىنىپ، پۇرسەتنى غەنىمەت بىلدى.","u bashqilarning qiyinchiliqidin paydilinip, pursetni ghenimet bildi."]],"事先通知":[["请事先通知我们。","بىزگە ئالدىن ئۇقتۇرۇڭ.","bizge aldin uqturung."]],"干酪素":[["干酪素是牛奶中提取的一种蛋白质。","كازېئىن سۈتتە بار بولغان بىر خىل ئاقسىلدۇر.","kazéin sütte bar bolghan bir xil aqsildur."]],"二氯甲烷":[["二氯甲烷是常见的有机溶剂。","دىكلورومېتان ئادەتتىكى ئورگانىك ئېرىتكۈچتۇر.","diklorométan adettiki organik éritküchtur."]],"二氯异三聚氰酸钠":[["二氯异三聚氰酸钠用于水处理。","دىكلورو ئىزوسىيانۇرىك كىسلاتا ناترىيى سۇ بىر تەرەپ قىلىشتا ئىشلىتىلىدۇ.","dikloro izosiyanurik kislata natriyi su bir terep qilishta ishlitilidu."]],"二水":[["二水是一种常见的化学物质。","دىسۇ ئادەتتىكى خىمىيىلىك ماددىدۇر.","disu adettiki ximiyilik maddidur."]],"二更":[["二更时分，街上已经很少有人了。","ئىككىنچى نۆۋەت ۋاقتىدا، كوچىدا ئادەم ئاز قالدى.","ikkinchi nöwet waqtida, kochida adem az qaldi."]],"亚达薛西":[["亚达薛西是古代波斯的一位重要君主。","ئارتاخشاشا قەدىمكى پارسىنىڭ بىر مۇھىم ھۆكۈمدارى.","artaxshasha qedimki parsining bir muhim hökümdari."]],"交通工具":[["自行车是一种常见的交通工具。","ۋېلىسىپىت كۆپ ئۇچرايدىغان قاتناش قورالى.","wélisipit köp uchraydighan qatnash qorali."]],"人工河":[["这条人工河灌溉农田。","بۇ سۈنئىي دەريا ئېتىز-ئېرىقلارنى سۇغىرىدۇ.","bu sün'iy derya étiz-ériqlarni sughiridu."]],"人形":[["机器人具有人形外观。","روبوتنىڭ ئىنسان شەكلىدىكى تاشقى كۆرۈنۈشى بار.","robotning insan sheklidiki tashqi körünüshi bar."]],"亭台楼阁":[["亭台楼阁是中国传统建筑中常见的元素。","جۇڭگونىڭ ئەنئەنىۋى بىناكارلىقىدا ساراي، سەھنە ۋە قەۋەتلىك بىنالار كۆپ ئۇچرايدىغان ئېلېمېنتلاردۇر.","junggoning en'eniwi binakarliqida saray, sehne we qewetlik binalar köp uchraydighan éléméntlardur."]],"什器":[["这些什器来自古代墓葬。","بۇ ئۇششاق ئەسۋابلار قەدىمكى قەبرىلەردىن كەلگەن.","bu ushshaq eswablar qedimki qebrilerdin kelgen."]],"令和":[["日本现在是令和时代。","ياپونىيە ھازىر رېيۋا دەۋرىدە.","yaponiye hazir réywa dewride."]],"仁义":[["他为人重仁义，乐于助人。","ئۇ ئىنسانپەرۋەرلىك ۋە ھەققانىيەتكە ئەھمىيەت بېرىدۇ، باشقىلارغا ياردەم قىلىشنى ياخشى كۆرىدۇ.","u insanperwerlik we heqqaniyetke ehmiyet béridu, bashqilargha yardem qilishni yaxshi köridu."]],"代填":[["请代填表格中的空白部分。","جەدۋەلدىكى بوش قىسىمنى تولدۇرۇپ بېرىڭ.","jedweldiki bosh qisimni toldurup béring."]],"以权压法":[["以权压法的行为必须受到谴责。","ھوقۇق بىلەن قانۇننى بېسىش قىلمىشى قاتتىق ئەيىبلىنىشى كېرەك.","hoquq bilen qanunni bésish qilmishi qattiq eyiblinishi kérek."]],"仙股":[["仙股是指那些具有巨大投资潜力的股票。","پەرى پاي چېكى چوڭ مەبلەغ سېلىش ئېھتىماللىقىغا ئىگە پاي چېكىلەرنى كۆرسىتىدۇ.","peri pay chéki chong meblegh sélish éhtimalliqigha ige pay chékilerni körsitidu."]],"佐佐木":[["佐佐木是一位著名的日本作家。","سازاكى داڭلىق ياپونىيە يازغۇچىسى.","sazaki dangliq yaponiye yazghuchisi."]],"你妈":[["你妈真厉害！","ئاپىڭىز ھەقىقەتەن كۈچلۈك!","apingiz heqiqeten küchlük!"]],"作弄":[["他作弄了朋友一番。","ئۇ دوستىنى بىر ئاز مازاق قىلدى.","u dostini bir az mazaq qildi."]],"佳冬乡":[["佳冬乡以独特的自然风光闻名。","جيادوڭ يېزىسى ئۆزىگە خاس تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","jyadong yézisi özige xas tebiiy menzirisi bilen tonulghan."]],"伸张":[["他伸张正义，揭露了腐败行为。","ئۇ ھەققانىيەتنى قوغداپ، چىرىكلىك ھەرىكىتىنى ئاشكارىلىدى.","u heqqaniyetni qoghdap, chiriklik herikitini ashkarilidi."]],"侏罗":[["侏罗时期的恐龙种类繁多。","يۇرا دەۋرىدىكى دىنوزاۋرلارنىڭ تۈرلىرى ناھايىتى كۆپ ئىدى.","yura dewridiki dinozawrlarning türliri nahayiti köp idi."]],"使用数量":[["请限制使用数量，避免浪费。","ئىشلىتىش مىقدارىنى چەكلەپ، ئىسراپچىلىقتىن ساقلىنىڭ.","ishlitish miqdarini cheklep, israpchiliqtin saqlining."]],"信物":[["这块玉佩是定情的信物。","بۇ يادە تاش مۇھەببەت بىلەنلىك ئىشەنچ بەلگىسى.","bu yade tash muhebbet bilenlik ishench belgisi."]],"信息化":[["信息化推动了现代社会的快速发展。","ئۇچۇرلاشتۇرۇش زامانىۋى جەمئىيەتنىڭ تېز تەرەققىياتىنى ئىلگىرى سۈردى.","uchurlashturush zamaniwi jem'iyetning téz tereqqiyatini ilgiri sürdi."]],"修昔底德":[["修昔底德是古代著名的历史学家。","فۇكىدىد ئەسلىدە قەدىمكى دەۋرنىڭ مەشھۇر تارىخچىسى.","fukidid eslide qedimki dewrning meshhur tarixchisi."]],"候审":[["案件正在候审阶段。","دەۋا سوتقا قويۇلۇش باسقۇچىدا تۇرۇۋاتىدۇ.","dewa sotqa qoyulush basquchida turuwatidu."]],"倚天屠龙记":[["《倚天屠龙记》很经典。","«يىتيەن تۇلۇڭجى» ئىنتايىن كلاسسىك.","«yityen tulungji» intayin klassik."]],"倒空":[["请把杯子倒空。","ستاكاننى قۇرۇق قىلىڭ.","stakanni quruq qiling."]],"俩钱":[["花俩钱就能解决。","ئازغىنا پۇل سەرپ قىلىپلا ھەل قىلغىلى بولىدۇ.","azghina pul serp qilipla hel qilghili bolidu."]],"假吏":[["假吏是古代临时官员。","يالغان ئەمەلدار قەدىمكى زاماندىكى ۋاقىتلىق ئەمەلدار ئىدى.","yalghan emeldar qedimki zamandiki waqitliq emeldar idi."]],"假小子":[["她是个假小子，爱冒险。","ئۇ يالغان ئوغۇل بالا، تەۋەككۈلچىلىك قىلىشنى ياخشى كۆرىدۇ.","u yalghan oghul bala, tewekkülchilik qilishni yaxshi köridu."]],"俯仰无愧":[["做人要俯仰无愧，问心无愧。","ئادەم بولۇش ئۈچۈن باش كۆتۈرۈپ ۋە ئېگىلىپ ئۇيالماستىن، ۋىجدانى ئالدىدا ئۇيالماستىن بولۇش كېرەك.","adem bolush üchün bash kötürüp we égilip uyalmastin, wijdani aldida uyalmastin bolush kérek."]],"假意":[["假意的道歉并不能解决问题。","ساختا كەچۈرۈم سوراش مەسىلىنى ھەل قىلالمايدۇ.","saxta kechürüm sorash mesilini hel qilalmaydu."]],"倩影":[["她的倩影映在湖面上。","ئۇنىڭ گۈزەل سايىسى كۆل يۈزىدە ئەكس ئەتتى.","uning güzel sayisi köl yüzide eks etti."]],"值此":[["值此佳节之际。","مۇبارەك بايرام پۇرسىتىدە.","mubarek bayram pursitide."]],"偷香窃玉":[["他偷香窃玉，行为不轨。","ئۇ خۇشپۇراق ۋە گۆھەر ئوغرىلايدۇ، قىلمىشى ناتوغرا.","u xushpuraq we göher oghrilaydu, qilmishi natoghra."]],"传闻证据":[["传闻证据可能不可靠。","ئىغۋا ئاساسىدىكى دەلىللەر ئىشەنچسىز بولۇشى مۇمكىن.","ighwa asasidiki deliller ishenchsiz bolushi mumkin."]],"优柔寡断":[["优柔寡断的人难以做出果断的决定。","ئىككىلەمچىلىك قىلىدىغان كىشىلەر قەتئىي قارار چىقىرىشتا قىيىنىچىلىق تارتىدۇ.","ikkilemchilik qilidighan kishiler qet'iy qarar chiqirishta qiyinichiliq tartidu."]],"元勋":[["这些元勋为革命立下汗马功劳。","بۇ ئۇلۇغ شەخسلەر ئىنقىلاب ئۈچۈن زور تۆھپە قوشتى.","bu ulugh shexsler inqilab üchün zor töhpe qoshti."]],"光照度":[["光照度会影响植物的光合作用。","نۇر چۈشۈش دەرىجىسى ئۆسۈملۈكلەرنىڭ فوتوسىنتېزىغا تەسىر كۆرسىتىدۇ.","nur chüshüsh derijisi ösümlüklerning fotosintézigha tesir körsitidu."]],"光斑":[["光斑是光线聚集形成的亮点。","يورۇقلۇق داغچىسى يورۇقلۇقنىڭ جەم بولۇشىدىن شەكىللەنگەن پارلاق نۇقتا.","yoruqluq daghchisi yoruqluqning jem bolushidin shekillengen parlaq nuqta."]],"元谋":[["元谋是云南省的一个历史名城。","يۈەنمۇ شۇ يۈننەن ئۆلكىسىدىكى بىر تارىخىي شەھەر.","yüenmu shu yünnen ölkisidiki bir tarixiy sheher."]],"免单":[["店家提供免单活动。","دۇكان ئەپۇ قىلىش پائالىيىتىنى تەمىنلەيدۇ.","dukan epu qilish paaliyitini teminleydu."]],"免疫学":[["免疫学是重要学科。","ئىممۇنىتېت ئىلمى مۇھىم پەن.","immunitét ilmi muhim pen."]],"兜抄":[["他试图兜抄过去，但被保安拦住了。","ئۇ ئۆتۈپ كەتمەكچى بولغان، ئەمما قوغدىغۇچىلار ئۇنى توسۇۋالدى.","u ötüp ketmekchi bolghan, emma qoghdighuchilar uni tosuwaldi."]],"克里米亚":[["克里米亚的地理位置十分战略重要。","كرىمىيەنىڭ جۇغراپىيەلىك ئورنى ئىنتايىن ئىستراتېگىيەلىك ئەھمىيەتكە ئىگە.","krimiyening jughrapiyelik orni intayin istratégiyelik ehmiyetke ige."]],"公母俩":[["公母俩一起照顾刚出生的幼崽。","ئەركەك-چىشى بىرلىكتە يېڭى تۇغۇلغان بالىسىنى بېقىپ پاراۋانلىق قىلىدۇ.","erkek-chishi birlikte yéngi tughulghan balisini béqip parawanliq qilidu."]],"公司理财":[["公司理财涉及资金的有效运用。","شىركەت مالىيە باشقۇرۇش مەبلەغنىڭ ئۈنۈملۈك ئىشلىتىلىشىنى ئۆز ئىچىگە ئالىدۇ.","shirket maliye bashqurush mebleghning ünümlük ishlitilishini öz ichige alidu."]],"公演":[["这场公演获得了观众的一致好评。","بۇ ئوچۇق نومۇر قويۇش توماشابىنلارنىڭ بىردەك ياخشى باھاسىغا ئېرىشتى.","bu ochuq nomur qoyush tomashabinlarning birdek yaxshi bahasigha érishti."]],"典章":[["古代典章制度规范了社会秩序。","قەدىمكى تۈزۈم-تەرتىپلەر جەمئىيەت تەرتىپىنى قېلىپلاشتۇرغان.","qedimki tüzüm-tertipler jem'iyet tertipini qéliplashturghan."]],"公开钥匙":[["这把是公开钥匙。","بۇ ئوچۇق ئاچقۇچ.","bu ochuq achquch."]],"净身出户":[["离婚后，他选择净身出户。","ئاجرىشىشتىن كېيىن، ئۇ ھېچ نەرسىسىز ئۆيدىن چىقىپ كەتتى.","ajrishishtin kéyin, u héch nersisiz öydin chiqip ketti."]],"列星":[["夜空中闪烁的列星令人惊叹不已。","كېچە ئاسمانىدا چاقناپ تۇرغان يۇلتۇزلار كىشىنى ھەيران قالدۇرىدۇ.","kéche asmanida chaqnap turghan yultuzlar kishini heyran qalduridu."]],"判别式":[["数学中的判别式很关键。","ماتېماتىكىدىكى پەرقلەندۈرگۈچ ئىنتايىن مۇھىم.","matématikidiki perqlendürgüch intayin muhim."]],"别具一格":[["这幅画风格别具一格。","بۇ رەسىمنىڭ ئۇسلۇبى ئالاھىدە.","bu resimning uslubi alahide."]],"到付":[["选择到付，收货时再付款。","يەتكۈزۈپ بېرىش ئۇسۇلىنى تاللاڭ، مالنى ئالغاندا پۇل تۆلەڭ.","yetküzüp bérish usulini tallang, malni alghanda pul töleng."]],"到现在":[["他到现在还没有完成作业。","ئۇ ھازىرغىچە تاپشۇرۇقىنى تۈگەتمىدى.","u hazirghiche tapshuruqini tügetmidi."]],"剖腹产手术":[["剖腹产手术风险较低。","قېرىن يېرىش ئوپېراتسىيەسىنىڭ خەۋپى بىر قەدەر تۆۋەن.","qérin yérish opératsiyesining xewpi bir qeder töwen."]],"别苗头":[["这个新政策别苗头，值得关注。","بۇ يېڭى سىياسەت باش كۆتۈرمەكتە، دىققەت قىلىشقا ئەرزىيدۇ.","bu yéngi siyaset bash kötürmekte, diqqet qilishqa erziydu."]],"刨子":[["他用刨子把木板打磨得光滑平整。","ئۇ رەندە بىلەن تاختاينى تۈزلەپ سىلىق قىلدى.","u rende bilen taxtayni tüzlep siliq qildi."]],"利诱":[["他用金钱利诱同事。","ئۇ پۇل بىلەن خىزمەتدىشىنى قىزىقتۇردى.","u pul bilen xizmetdishini qiziqturdi."]],"利钱":[["他靠利钱发了财。","ئۇ پايدا پۇلى بىلەن بايىدى.","u payda puli bilen bayidi."]],"加减号":[["加减号用于表示数学运算。","قوشۇش ۋە ئېلىش بەلگىسى ماتېماتىكىلىق ھېسابلاشنى ئىپادىلەشكە ئىشلىتىلىدۇ.","qoshush we élish belgisi matématikiliq hésablashni ipadileshke ishlitilidu."]],"包里斯":[["包里斯是著名的音乐家。","بورىس مەشھۇر مۇزىكانت.","boris meshhur muzikant."]],"匪徒":[["匪徒们被警方一网打尽。","قاراقچىلار ساقچىلار تەرىپىدىن بىرلا ۋاقىتتا تۇتۇلدى.","qaraqchilar saqchilar teripidin birla waqitta tutuldi."]],"千金一诺":[["他的千金一诺令人敬佩。","ئۇنىڭ مىڭ ئالتۇنلۇق ۋەدىسى كىشىلەرنى ھەيران قالدۇرىدۇ.","uning ming altunluq wedisi kishilerni heyran qalduridu."]],"千克":[["千克是国际单位制中的质量单位。","كىلوگرام خەلقئارا بىرلىك سىستېمىسىدىكى ماسسا بىرلىكى.","kilogram xelq'ara birlik sistémisidiki massa birliki."]],"北江":[["北江水流湍急。","شىمالىي دەريا سۈيى تېز ئېقىدۇ.","shimaliy derya süyi téz éqidu."]],"北洋水师":[["北洋水师是清朝的海军力量。","شىمالىي ئوكيان دېڭىز ئارمىيىسى چىڭ سۇلالىسىنىڭ دېڭىز ئارمىيە كۈچى.","shimaliy okyan déngiz armiyisi ching sulalisining déngiz armiye küchi."]],"南极洲":[["南极洲是世界上最大的岛屿。","جەنۇبىي قۇتۇپ قىتئەسى دۇنيادىكى ئەڭ چوڭ ئارال.","jenubiy qutup qit'esi dunyadiki eng chong aral."]],"千丝万缕":[["两国关系有着千丝万缕的联系。","ئىككى دۆلەتنىڭ مۇناسىۋىتى مىڭ-مىڭ تالالىق چىن چىرمىشىپ كەتكەن.","ikki döletning munasiwiti ming-ming talaliq chin chirmiship ketken."]],"千里之堤，溃于蚁穴":[["千里之堤，溃于蚁穴，小事不可轻视。","مىڭ چاقىرىملىق دەريا بويى چۈمۈلە ئۇۋىسىدىن بۇزۇلىدۇ، كىچىك ئىشلارنى يېنىك كۆرمەسلىك كېرەك.","ming chaqirimliq derya boyi chümüle uwisidin buzulidu, kichik ishlarni yénik körmeslik kérek."]],"博蒂":[["博蒂是当地一位著名画家。","بوتى يەرلىك داڭلىق رەسسام.","boti yerlik dangliq ressam."]],"南江":[["南江是一条贯穿山谷的河流。","جەنۇبىي جياڭ جىلغىنى بويلاپ ئاقىدىغان بىر دەريا.","jenubiy jyang jilghini boylap aqidighan bir derya."]],"南皮县":[["南皮县以美食闻名。","جەنۇبىي پى ناھىيىسى تائاملىرى بىلەن داڭلىق.","jenubiy pi nahiyisi taamliri bilen dangliq."]],"卡尔巴拉":[["卡尔巴拉位于伊拉克南部。","كەربەلا ئىراقنىڭ جەنۇبىدا جايلاشقان.","kerbela iraqning jenubida jaylashqan."]],"原产":[["这款酒的原产地位于法国。","بۇ ھاراقنىڭ ئەسلىي ئىشلەپچىقىرىلغان يېرى فرانسىيەدە.","bu haraqning esliy ishlepchiqirilghan yéri fransiyede."]],"又称":[["这种植物又称“千年草”。","بۇ خىل ئۆسۈملۈك يەنە «مىڭ يىللىق ئوت» دەپ ئاتىلىدۇ.","bu xil ösümlük yene «ming yilliq ot» dep atilidu."]],"友好区":[["这个友好区促进了文化交流。","بۇ دوستلۇق رايونى مەدەنىيەت ئالماشتۇرۇشنى ئىلگىرى سۈردى.","bu dostluq rayoni medeniyet almashturushni ilgiri sürdi."]],"卡恩":[["卡恩是一位著名的足球教练。","كاھن بىر داڭلىق پۇتبول مۇرەببىيى.","kahn bir dangliq putbol murebbiyi."]],"印刷量":[["印刷量需要根据需求调整。","بېسىش مىقدارىنى ئېھتىياجغا قاراپ تەڭشەش كېرەك.","bésish miqdarini éhtiyajgha qarap tengshesh kérek."]],"口沫":[["他生气时口沫横飞。","ئۇ ئاچچىقلانغاندا ئېغىزىدىن تۈكۈرۈكى چېچىلىدۇ.","u achchiqlanghanda éghizidin tükürüki chéchilidu."]],"口淫":[["这种口淫行为不可取。","بۇنداق ئېغىز بىلەن قىلىنغان جىنسىي ھەرىكەت قوبۇل قىلىنمايدۇ.","bundaq éghiz bilen qilinghan jinsiy heriket qobul qilinmaydu."]],"受够":[["我受够了这种不公平的待遇。","مەن بۇ خىل ئادىل بولمىغان مۇئامىلىدىن زېرىكتىم.","men bu xil adil bolmighan muamilidin zériktim."]],"取款":[["我打算去银行取款。","مەن بانكىغا پۇل ئېلىشقا بارماقچى.","men bankigha pul élishqa barmaqchi."]],"只限于":[["这项服务只限于会员。","بۇ مۇلازىمەت پەقەت ئەزالىارغىلا چەكلىك.","bu mulazimet peqet ezaliarghila cheklik."]],"可得到":[["这个结果很容易可得到。","بۇ نەتىجىنى ئاسانلا قولغا كەلتۈرگىلى بولىدۇ.","bu netijini asanla qolgha keltürgili bolidu."]],"古根罕喷气推进研究中心":[["古根罕喷气推进研究中心位于加州。","گۇگېنھېيم رېئاكتىپ ھەرىكەتلەندۈرۈش تەتقىقات مەركىزى كالىفورنىيەدە جايلاشقان.","gugénhéym réaktip heriketlendürüsh tetqiqat merkizi kaliforniyede jaylashqan."]],"古冶区":[["古冶区是唐山市的一部分。","گۇيې رايونى تاڭشەن شەھىرىنىڭ بىر قىسمى.","guyé rayoni tangshen shehirining bir qismi."]],"吃得苦中苦，方为人上人":[["吃得苦中苦，方为人上人。","ئاچچىقنىڭ ئاچچىقىنى يېگەن ئادەم ئادەملەر ئۈستىدە بولىدۇ.","achchiqning achchiqini yégen adem ademler üstide bolidu."]],"吃醋":[["他看到女友和异性说话就吃醋。","ئۇ قىز دوستىنىڭ باشقا جىنسدىكىلەر بىلەن سۆزلىشىشىنى كۆرسە قىزغىنىدۇ.","u qiz dostining bashqa jinsdikiler bilen sözlishishini körse qizghinidu."]],"吃斋":[["他今天吃斋，不吃肉。","ئۇ بۈگۈن روزا تۇتىدۇ، گۆش يېمەيدۇ.","u bügün roza tutidu, gösh yémeydu."]],"同心县":[["同心县位于贵州省北部。","تۇڭشىن ناھىيىسى گۈيژۇ ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","tungshin nahiyisi güyzhu ölkisining shimalida jaylashqan."]],"同盟军":[["同盟军成功解放了多个城市。","بىرلەشمە ئارمىيە كۆپلىگەن شەھەرلەرنى مۇۋەپپەقىيەتلىك ئازاد قىلدى.","birleshme armiye köpligen sheherlerni muweppeqiyetlik azad qildi."]],"吊裆裤":[["这种吊裆裤穿起来很不舒服。","بۇ خىل ئاسما پاجىمىلىق ئىشتان كىيگەندە بەك ئىسسىق كېلىدۇ.","bu xil asma pajimiliq ishtan kiygende bek issiq kélidu."]],"名人录":[["这本名人录记录了众多名人。","بۇ داڭلىق شەخسلەر تىزىملىكى نۇرغۇن داڭلىق شەخسلەرنى خاتىرىلىگەن.","bu dangliq shexsler tizimliki nurghun dangliq shexslerni xatiriligen."]],"名录":[["这份名录包含所有成员。","بۇ تىزىملىك بارلىق ئەزالارنى ئۆز ئىچىگە ئالىدۇ.","bu tizimlik barliq ezalarni öz ichige alidu."]],"吐司":[["他烤了一片吐司面包。","ئۇ بىر پارچە تۇستا نان پىشۇردى.","u bir parche tusta nan pishurdi."]],"君臣":[["君臣关系在古代政治中至关重要。","پادىشاھ بىلەن ۋەزىر ئوتتۇرىسىدىكى مۇناسىۋەت قەدىمكى سىياسەتتە ئىنتايىن مۇھىم.","padishah bilen wezir otturisidiki munasiwet qedimki siyasette intayin muhim."]],"合数":[["这些数字的合数各不相同。","بۇ سانلارنىڭ مۇرەككەپ سانلىرى ھەر خىل.","bu sanlarning murekkep sanliri her xil."]],"吲哚":[["吲哚是一种有机化合物。","ئىندول بىر خىل ئورگانىك بىرىكمە.","indol bir xil organik birikme."]],"和平统一":[["我们追求和平统一。","بىز تىنچلىق بىلەن بىرلىككە كېلىشنى ئىزدەيمىز.","biz tinchliq bilen birlikke kélishni izdeymiz."]],"哈啰":[["哈啰，你准备好了吗？","سالام، سەن تەييار بولدۇڭمۇ؟","salam, sen teyyar boldungmu?"]],"哄抬":[["有人故意哄抬物价，引发不满。","بەزىلەر قەستەن باھانى ئۆرلىتىپ، نارازىلىق قوزغىدى.","beziler qesten bahani örlitip, naraziliq qozghidi."]],"含碳":[["这种材料含碳量较低。","بۇ خىل ماتېرىيالنىڭ كاربون تەركىبى تۆۋەن.","bu xil matériyalning karbon terkibi töwen."]],"咕哝":[["他咕哝着抱怨天气太冷。","ئۇ ھاۋانىڭ بەك سوغۇقلىقىدىن غۇڭۇلداپ زارلاندى.","u hawaning bek soghuqliqidin ghunguldap zarlandi."]],"员山乡":[["员山乡风景优美，游客众多。","يۈەنشەن يېزىسىنىڭ مەنزىرىسى گۈزەل، ساياھەتچىلەر كۆپ.","yüenshen yézisining menzirisi güzel, sayahetchiler köp."]],"员林镇":[["员林镇以传统小吃闻名。","يۈەنلىن بازىرى ئەنئەنىۋى تائاملىرى بىلەن داڭلىق.","yüenlin baziri en'eniwi taamliri bilen dangliq."]],"唐氏症":[["唐氏症是一种染色体异常疾病。","تاڭ ئەپەندى كېسىلى خромوسوما نورمالسىزلىقى كېسىلى.","tang ependi késili xромosoma normalsizliqi késili."]],"品等":[["商品分为不同品等以满足需求。","ماللار ئېھتىياجنى قاندۇرۇش ئۈچۈن تۈرلۈك دەرىجىلەرگە بۆلۈنگەن.","mallar éhtiyajni qandurush üchün türlük derijilerge bölüngen."]],"商业应用":[["这款商业应用功能非常强大。","بۇ سودا ئەپلىكىمىسىنىڭ ئىقتىدارى ئىنتايىن كۈچلۈك.","bu soda eplikimisining iqtidari intayin küchlük."]],"商都县":[["商都县是河北省的一个县城。","شاڭدۇ ناھىيىسى خېبېي ئۆلكىسىدىكى بىر ناھىيە.","shangdu nahiyisi xébéy ölkisidiki bir nahiye."]],"售卖":[["这家店正在售卖纪念品。","بۇ دۇكان ئەسكەرتىش بۇيۇملىرىنى سېتىۋاتىدۇ.","bu dukan eskertish buyumlirini sétiwatidu."]],"哨子":[["哨子可以用来指挥交通。","پىششىقنى قاتناشنى باشقۇرۇشقا ئىشلەتكىلى بولىدۇ.","pishshiqni qatnashni bashqurushqa ishletkili bolidu."]],"哪吒":[["哪吒是《封神演义》里的英雄人物。","نېجا پەنلەشتۈرۈش رىۋايىتىدىكى قەھرىمان شەخس.","néja penleshtürüsh riwayitidiki qehriman shexs."]],"唇膏":[["她随身带着唇膏，随时补妆。","ئۇ لەۋ سۈرمىسىنى يېنىدا ئېلىپ يۈرۈپ، ھەر ۋاقىت يېڭىلايدۇ.","u lew sürmisini yénida élip yürüp, her waqit yéngilaydu."]],"丧权辱国":[["条约导致丧权辱国，民族蒙羞。","بۇ شەرتنامە ھوقۇقىمىزنى يوقىتىپ، دۆلەتنى خار قىلدى، مىللەتنى شەرمەندە قىلدى.","bu shertname hoquqimizni yoqitip, döletni xar qildi, milletni shermende qildi."]],"乔治·奥威尔":[["乔治·奥威尔是著名作家。","جورج ئورۋېل مەشھۇر يازغۇچى.","jorj orwél meshhur yazghuchi."]],"单片机":[["单片机广泛应用于电子设备中。","يالغۇز پارچە كومپيۇتېر ئېلېكترونلۇق ئۈسكۈنىلەردە كەڭ قوللىنىلىدۇ.","yalghuz parche kompyutér éléktronluq üskünilerde keng qollinilidu."]],"嘎然":[["声音嘎然停止。","ئاۋاز غالتى-غۇلتى توختىدى.","awaz ghalti-ghulti toxtidi."]],"嘉宝果":[["嘉宝果是一种热带水果。","جىياباۋ مېۋىسى بىر خىل تروپىك مېۋىدۇر.","jiyabaw méwisi bir xil tropik méwidur."]],"嘴甜":[["她嘴甜，说话让人舒服。","ئۇنىڭ ئاغزى تاتلىق، سۆزلىرى كىشىلەرنى خۇشال قىلىدۇ.","uning aghzi tatliq, sözliri kishilerni xushal qilidu."]],"唝吥":[["这种植物叫唝吥，有药用价值。","بۇ ئۆسۈملۈك كامپۇچىيە دەپ ئاتىلىدۇ، دورىلىق قىممىتى بار.","bu ösümlük kampuchiye dep atilidu, doriliq qimmiti bar."]],"四元数":[["四元数在数学中广泛应用。","تۆت ئېلېمېنتلىق سان ماتېماتىكىدا كەڭ قوللىنىلىدۇ.","töt éléméntliq san matématikida keng qollinilidu."]],"四散":[["人群在混乱中四散开来。","ئادەم توپى قالايمىقانچىلىق ئىچىدە تۆت تەرەپكە تارقاپ كەتتى.","adem topi qalaymiqanchiliq ichide töt terepke tarqap ketti."]],"回覆":[["请尽快回覆我的邮件。","ئېلخېتىمنى تېزدىن قايتۇرۇپ بېرىڭ.","élxétimni tézdin qayturup béring."]],"回视":[["他回视过去，感慨万千。","ئۇ ئۆتمۈشكە قايتا نەزەر سېلىپ، ھېسسىياتى تاشقىنلىق تاشتى.","u ötmüshke qayta nezer sélip, héssiyati tashqinliq tashti."]],"圈地":[["他们开始圈地建房子。","ئۇلار يەر چەمبىرەكلەپ ئۆي سېلىشنى باشلىدى.","ular yer chembireklep öy sélishni bashlidi."]],"圈数":[["比赛已经完成了五圈数。","مۇسابىقە بەش ئايلانمىنى تاماملىدى.","musabiqe besh aylanmini tamamlidi."]],"国家安全局":[["国家安全局负责维护国家的安全。","دۆلەت بىخەتەرلىك ئىدارىسى دۆلەت بىخەتەرلىكىنى قوغداشقا مەسئۇل.","dölet bixeterlik idarisi dölet bixeterlikini qoghdashqa mes'ul."]],"围兜":[["宝宝吃饭时，妈妈给他系上围兜。","بوۋاق تاماق يېگەندە، ئاپىسى ئۇنىڭغا ئالدىنقى ئالدامچىنى باغلاپ قويىدۇ.","bowaq tamaq yégende, apisi uninggha aldinqi aldamchini baghlap qoyidu."]],"土库曼":[["土库曼语是一种语言。","تۈركمەن تىلى بىر خىل تىل.","türkmen tili bir xil til."]],"图瓦":[["图瓦是一个少数民族。","تۇۋا ئاز سانلىق مىللەت.","tuwa az sanliq millet."]],"国际机场":[["国际机场连接着不同国家，促进国际间的交流。","خەلقئارا ئايرودروم ئوخشاش بولمىغان دۆلەتلەرنى تۇتاشتۇرۇپ، خەلقئارا ئالاقىنى ئىلگىرى سۈرىدۇ.","xelq'ara ayrodrom oxshash bolmighan döletlerni tutashturup, xelq'ara alaqini ilgiri süridu."]],"土谷祠":[["土谷祠是历史悠久的古庙。","تۇگۇتسى ئىبادەتخانىسى ئۇزۇن تارىخقا ئىگە قەدىمكى ئىبادەتخانىدۇر.","tugutsi ibadetxanisi uzun tarixqa ige qedimki ibadetxanidur."]],"土耳其旋转烤肉":[["土耳其旋转烤肉是当地著名的美食。","تۈركىيە ئايلانما گۆش كاۋابى يەرلىك ئاتاقلىق تائامدۇر.","türkiye aylanma gösh kawabi yerlik ataqliq taamdur."]],"国防预算":[["国防预算需合理分配。","دۆلەت مۇداپىئە بۇدجېتىنى مۇۋاپىق تەقسىملەش كېرەك.","dölet mudapie budjétini muwapiq teqsimlesh kérek."]],"地铁站":[["地铁站是城市公共交通的重要枢纽。","مېترو بېكىتى شەھەر ئاممىۋى قاتناشىنىڭ مۇھىم تۈگۈنىدۇر.","métro békiti sheher ammiwi qatnashining muhim tügünidur."]],"垛口":[["垛口是城墙上的射击口。","دۇوكو ئېغىزى شەھەر تامىدىكى ئېتىش ئېغىزى.","duoko éghizi sheher tamidiki étish éghizi."]],"地盘":[["每个帮派都有自己的地盘。","ھەر بىر گۇرۇھنىڭ ئۆز زېمىنى بار.","her bir guruhning öz zémini bar."]],"地缘":[["地缘关系影响国家间的合作。","يەر مۇناسىۋىتى دۆلەتلەر ئارا ھەمكارلىققا تەسىر كۆرسىتىدۇ.","yer munasiwiti döletler ara hemkarliqqa tesir körsitidu."]],"垂泪":[["他垂泪告别了亲人。","ئۇ كۆز يېشى بىلەن يېقىنلىرى بىلەن خوشلاشتى.","u köz yéshi bilen yéqinliri bilen xoshlashti."]],"基波":[["基波是信号的主要成分。","تولقۇن ئاساسىي ئىستېرېئولۇق تەركىبىدۇر.","tolqun asasiy istéréoluq terkibidur."]],"堰塞湖":[["这个堰塞湖的形成非常危险。","بۇ توسما كۆلنىڭ شەكىللەنىشى ئىنتايىن خەتەرلىك.","bu tosma kölning shekillenishi intayin xeterlik."]],"报亭":[["报亭里摆放着各种报纸杂志。","گېزىت-ژۇرنال دۇكىنىدا تۈرلۈك گېزىت-ژۇرناللار قويۇلغان.","gézit-zhurnal dukinida türlük gézit-zhurnallar qoyulghan."]],"塞浦路斯":[["塞浦路斯是地中海的一个岛国。","سېپرۇس ئوتتۇرا دېڭىزدىكى بىر ئارال دۆلىتى.","séprus ottura déngizdiki bir aral döliti."]],"壁垒森严":[["边境壁垒森严，难以穿越。","چېگرا قورغىنى ئىنتايىن مۇستەھكەم، ئۆتۈش قىيىن.","chégra qorghini intayin mustehkem, ötüsh qiyin."]],"堆高机":[["堆高机用于搬运重物。","تەكشىلىگۈچ ئېغىر يۈكلەرنى يۆتكەشتە ئىشلىتىلىدۇ.","tekshiligüch éghir yüklerni yötkeshte ishlitilidu."]],"墨子":[["墨子是战国时期著名的思想家。","موزى جەڭگى دەۋرىدىكى داڭلىق مۇتەپەككۇردۇر.","mozi jenggi dewridiki dangliq mutepekkurdur."]],"壁炉":[["壁炉旁边放着舒适的沙发。","تام ئوچىقىنىڭ يېنىدا راھەتلىك دىۋان قويۇلغان.","tam ochiqining yénida rahetlik diwan qoyulghan."]],"壬辰倭乱":[["壬辰倭乱是朝鲜历史上的重要事件。","رېنچېن ياپون باسقۇنچىلىقى كورېيە تارىخىدىكى مۇھىم ۋەقە.","rénchén yapon basqunchiliqi koréye tarixidiki muhim weqe."]],"外交家":[["外交家以智慧化解危机。","سىرتقى ئىشلار مۇتەخەسسىسى پاراسەت بىلەن كىرىزىسنى ھەل قىلىدۇ.","sirtqi ishlar mutexessisi paraset bilen kirizisni hel qilidu."]],"外国媒体":[["外国媒体关注此事。","چەت ئەل ئاخبارات ۋاسىتىلىرى بۇ ئىشقا دىققەت قىلدى.","chet el axbarat wasitiliri bu ishqa diqqet qildi."]],"多层材":[["这种多层材料非常耐用。","بۇ خىل كۆپ قەۋەتلىك ماتېرىيال ئىنتايىن چىداملىق.","bu xil köp qewetlik matériyal intayin chidamliq."]],"大口径":[["大口径的炮威力更强。","چوڭ ئېغىزلىق توپنىڭ كۈچى تېخىمۇ كۈچلۈك.","chong éghizliq topning küchi téximu küchlük."]],"大伯子":[["大伯子对弟媳一直都很照顾。","چوڭ ئاكا ئىنىسىنىڭ خوتۇنىغا دائىم كۆيۈمچانلىق كۆرسىتىپ كەلدى.","chong aka inisining xotunigha daim köyümchanliq körsitip keldi."]],"够得着":[["这个按钮我够得着。","بۇ كۇنۇپكىغا مەن يېتەلەيمەن.","bu kunupkigha men yételeymen."]],"大写字母":[["大写字母在英语中很重要。","چوڭ ھەرپلەر ئىنگلىز تىلىدا ئىنتايىن مۇھىم.","chong herpler ingliz tilida intayin muhim."]],"外设":[["电脑的外设包括键盘、鼠标和显示器等。","كومپيۇتېرنىڭ تاشقى ئۈسكۈنىلىرىگە كلاوىاتۇرا، چاشقىنەك ۋە كۆرسىتىش ئېكرانى قاتارلىقلار كىرىدۇ.","kompyutérning tashqi üskünilirige klaoiatura, chashqinek we körsitish ékrani qatarliqlar kiridu."]],"大环":[["大环是城市交通的重要一环。","چوڭ ھالقا شەھەر قاتناشىنىڭ مۇھىم بىر ھالقىسى.","chong halqa sheher qatnashining muhim bir halqisi."]],"天文学":[["天文学研究宇宙中的天体。","ئاسترونومىيە ئالەمدىكى ئاسمان جىسىملىرىنى تەتقىق قىلىدۇ.","astronomiye alemdiki asman jisimlirini tetqiq qilidu."]],"天旱":[["严重的天旱导致农作物歉收。","ئېغىر قۇرغاقچىلىق يېزا ئىگىلىك مەھسۇلاتلىرىنىڭ كەم بولۇشىغا سەۋەب بولدى.","éghir qurghaqchiliq yéza igilik mehsulatlirining kem bolushigha seweb boldi."]],"天山":[["天山是中国西部的重要山脉。","تەڭرىتاغ جۇڭگونىڭ غەربىي قىسمىدىكى مۇھىم تاغ تىزمىسىدۇر.","tengritagh junggoning gherbiy qismidiki muhim tagh tizmisidur."]],"天柱":[["天柱是支撑天空的柱子。","تەڭرى ئۈستۈنى ئاسماننى كۆتۈرۈپ تۇرىدىغان ئۈستۈندۇر.","tengri üstüni asmanni kötürüp turidighan üstündur."]],"天花":[["天花是一种古老的传染病。","ئاسمان گۈلى قەدىمىي بىر يۇقۇملۇق كېسەللىكتۇر.","asman güli qedimiy bir yuqumluq késelliktur."]],"夯具":[["夯具用于加固地面。","توقماق ئۈسكۈنىسى زېمىننى مۇستەھكەملەشكە ئىشلىتىلىدۇ.","toqmaq üskünisi zéminni mustehkemleshke ishlitilidu."]],"失调电压":[["失调电压可能损坏设备。","تەڭپۇڭسىزلىق بېسىمى ئۈسكۈنىلەرنى بۇزۇپ قويۇشى مۇمكىن.","tengpungsizliq bésimi üskünilerni buzup qoyushi mumkin."]],"夹持":[["他夹持着工具。","ئۇ ئەسۋابنى قىسىپ تۇرۇۋاتىدۇ.","u eswabni qisip turuwatidu."]],"套钟":[["套钟是古老的计时工具。","يەكتەك سائەت قەدىمىي ۋاقىت ئۆلچەش قورالىدۇر.","yektek saet qedimiy waqit ölchesh qoralidur."]],"好戏还在后头":[["好戏还在后头，别急。","ئەسلى تاماشا كەينىدە، ئالدىرما.","esli tamasha keynide, aldirma."]],"妖精":[["山里常有妖精出没。","تاغلاردا جادۇگەرلەر كۆپ ئۇچرايدۇ.","taghlarda jadugerler köp uchraydu."]],"如泣如诉":[["她的话语如泣如诉。","ئۇنىڭ سۆزلىرى يىغلاپ-سىڭرىگەندەك تەسىرلىك.","uning sözliri yighlap-singrigendek tesirlik."]],"如臂使指":[["他指挥得如臂使指，毫无阻碍。","ئۇ قوماندانلىقنى قولدەك ئىشلىتىپ، ھېچقانداق توسالغۇسىز ئېلىپ باردى.","u qomandanliqni qoldek ishlitip, héchqandaq tosalghusiz élip bardi."]],"如蛆附骨":[["烦恼如蛆附骨，挥之不去。","غەم-قايغۇ گويا سۆڭەككە چاپلاشقان قۇرتتەك، كېتىپ قالمايدۇ.","ghem-qayghu goya söngekke chaplashqan qurttek, kétip qalmaydu."]],"威玛共和国":[["威玛共和国是历史上的一个国家。","ۋىيما جۇمھۇرىيىتى تارىختىكى بىر دۆلەت.","wiyma jumhuriyiti tarixtiki bir dölet."]],"威厉":[["他的眼神威厉逼人。","ئۇنىڭ كۆز قارىشى ھەيۋەتلىك ۋە بېسىملىق.","uning köz qarishi heywetlik we bésimliq."]],"姒文命":[["姒文命是古代贤王。","سى ۋېنمىڭ قەدىمكى زاماندىكى دانا پادىشاھ ئىدى.","si wénming qedimki zamandiki dana padishah idi."]],"姨奶奶":[["姨奶奶是母亲的祖母，德高望重。","مومامنىڭ ئانىسى ئۇلۇغ ئورۇنغا ئىگە.","momamning anisi ulugh orungha ige."]],"姨姐":[["这位姨姐是妈妈的亲姐姐。","بۇ تاغا ئاچا ئانامنىڭ ئاچىسى.","bu tagha acha anamning achisi."]],"姐妹花":[["那对姐妹花在学校里非常受欢迎。","ئۇ سىڭىل-ئاچىلار مەكتەپتە ئىنتايىن ئالقىشلىق.","u singil-achilar mektepte intayin alqishliq."]],"妇道人家":[["她是个典型的妇道人家。","ئۇ تىپىك بىر ئايال كىشى.","u tipik bir ayal kishi."]],"媒人":[["媒人负责为双方牵线搭桥。","سۆيچى ئىككى تەرەپ ئۈچۈن ئارىلىق ئورنىتىپ كۆۋرۈك سالىدۇ.","söychi ikki terep üchün ariliq ornitip köwrük salidu."]],"子宫内避孕器":[["子宫内避孕器需要医生安装。","بالىياتقۇ ئىچىلىك پەرقلەندۈرگۈچىنى دوختۇر ئورنىتىشى كېرەك.","baliyatqu ichilik perqlendürgüchini doxtur ornitishi kérek."]],"宋体":[["宋体是一种常见的汉字印刷字体。","سۇڭتى خەت نۇسخىسى ئادەتتە كۆرۈلىدىغان بىر خەنزۇچە بېسىپ چىقىرىش خەت نۇسخىسى.","sungti xet nusxisi adette körülidighan bir xenzuche bésip chiqirish xet nusxisi."]],"宜黄":[["宜黄县隶属于抚州市管辖。","يىخۇاڭ ناھىيىسى فۇجۇ شەھىرىنىڭ باشقۇرۇشىغا قارايدۇ.","yixuang nahiyisi fuju shehirining bashqurushigha qaraydu."]],"密斯脱":[["他是一位名叫密斯脱的外国朋友。","ئۇ مىستو ئىسىملىك چەتئەللىك دوستىدۇر.","u misto isimlik chet'ellik dostidur."]],"实分析":[["实分析是数学分支。","ئەمەلىي ئانالىز ماتېماتىكىنىڭ بىر تارمىقىدۇر.","emeliy analiz matématikining bir tarmiqidur."]],"富锦市":[["富锦市是辽宁省的重要工业城市。","فۇجىن شەھىرى لياۋنىڭ ئۆلكىسىنىڭ مۇھىم سانائەت شەھىرى.","fujin shehiri lyawning ölkisining muhim sanaet shehiri."]],"宁安":[["宁安的环境非常优美。","نىڭئەننىڭ مۇھىتى ئىنتايىن گۈزەل.","ning'enning muhiti intayin güzel."]],"宽待":[["公司对员工宽待有加。","شىركەت خىزمەتچىلەرگە كەڭ مۇئامىلە قىلىدۇ.","shirket xizmetchilerge keng muamile qilidu."]],"寓教于乐":[["老师通过游戏将知识寓教于乐。","ئوقۇتقۇچى ئويۇن ئارقىلىق بىلىمنى سەمىمىي ئوقۇتۇش بىلەن بىرلەشتۈردى.","oqutquchi oyun arqiliq bilimni semimiy oqutush bilen birleshtürdi."]],"封三":[["封三页刊登了本期杂志的封面故事。","ئۈچىنچى مۇقاۋا بېتىدە بۇ سان ژۇرنالىنىڭ مۇقاۋا ھېكايىسى بېسىلدى.","üchinchi muqawa bétide bu san zhurnalining muqawa hékayisi bésildi."]],"封丘县":[["封丘县是当地重要的农业产区。","فېڭچيۇ ناھىيىسى يەرلىكنىڭ مۇھىم يېزا ئىگىلىك ئىشلەپچىقىرىش رايونىدۇر.","féngchyu nahiyisi yerlikning muhim yéza igilik ishlepchiqirish rayonidur."]],"专利药品":[["专利药品价格高。","پاتېنت دورىلىرىنىڭ باھاسى قىممەت.","patént dorilirining bahasi qimmet."]],"对证":[["请提供证据以进行对证。","ئىسپات تەمىنلەپ دەلىللەش ئېلىپ بېرىڭ.","ispat teminlep delillesh élip béring."]],"小受":[["他是小说里的小受。","ئۇ رومان ئىچىدىكى كىچىك قوبۇل.","u roman ichidiki kichik qobul."]],"小心眼":[["他有点小心眼，容易生气。","ئۇ سەل كىچىك كۆڭۈللۈك، ئاسان ئاچچىقلىنىدۇ.","u sel kichik köngüllük, asan achchiqlinidu."]],"小店":[["这家小店卖的手工饼干味道很好。","بۇ كىچىك دۇكاندا سېتىلىدىغان قولدا ياسالغان پېچىنە تەمى ناھايىتى ياخشى.","bu kichik dukanda sétilidighan qolda yasalghan péchine temi nahayiti yaxshi."]],"小𥻗子":[["小𥻗子是一种稀有鸟类。","كىچىك تاشقارا قۇشى ئاز ئۇچرايدىغان قۇش تۈرى.","kichik tashqara qushi az uchraydighan qush türi."]],"少先队":[["他加入了少先队。","ئۇ پىئونېرلار ئۇيۇشمىسىغا كىردى.","u pionérlar uyushmisigha kirdi."]],"小狗":[["小狗活泼可爱，惹人喜爱。","كىچىك ئىت جانلىق ۋە يېقىملىق، كىشىلەرنىڭ ياقتۇرۇشىغا ئېرىشىدۇ.","kichik it janliq we yéqimliq, kishilerning yaqturushigha érishidu."]],"尿片":[["宝宝用尿片睡觉很安心。","بوۋاق پەمپەرس بىلەن ئۇخلىسا ئىنتايىن خاتىرجەم بولىدۇ.","bowaq pempers bilen uxlisa intayin xatirjem bolidu."]],"尿生殖管道":[["尿生殖管道结构复杂。","سۈيدۈك تەناسىب يولىنىڭ قۇرۇلمىسى مۇرەككەپ.","süydük tenasib yolining qurulmisi murekkep."]],"屏南":[["屏南是一个风景优美的地方。","پىڭنەن مەنزىرىسى گۈزەل بىر جايدۇر.","pingnen menzirisi güzel bir jaydur."]],"尾闾骨":[["尾闾骨是脊椎的一部分。","قۇيرۇق ئومۇرتقىسى ئومۇرتقا تىزىملىكىنىڭ بىر قىسمى.","quyruq omurtqisi omurtqa tizimlikining bir qismi."]],"山竹":[["山竹是一种强台风。","تاغ مېۋىسى كۈچلۈك تيفۇندۇر.","tagh méwisi küchlük tyfundur."]],"居位":[["他居位显赫，备受尊敬。","ئۇ يۇقىرى مەنسەپتە تۇرىدۇ، كۆپ ھۆرمەتكە سازاۋەر.","u yuqiri mensepte turidu, köp hörmetke sazawer."]],"冈田":[["冈田是这家公司的总经理。","ئوكادا بۇ شىركەتنىڭ باش دىرېكتورى.","okada bu shirketning bash diréktori."]],"岷县":[["岷县位于甘肃省南部。","مىن ناھىيىسى گەنسۇ ئۆلكىسىنىڭ جەنۇبىدا جايلاشقان.","min nahiyisi gensu ölkisining jenubida jaylashqan."]],"嵩山":[["嵩山是中国著名的五岳之一。","سوڭشەن جۇڭگونىڭ مەشھۇر بەش مۇقەددەس تېغىنىڭ بىرى.","songshen junggoning meshhur besh muqeddes téghining biri."]],"工作队":[["工作队深入农村开展调研活动。","خىزمەت ئەترىتى يېزىلارغا چوڭقۇر كىرىپ تەكشۈرۈش پائالىيىتى ئېلىپ باردى.","xizmet etriti yézilargha chongqur kirip tekshürüsh paaliyiti élip bardi."]],"已婚":[["她已婚并育有两个孩子。","ئۇ ئاللىبۇرۇن توي قىلغان ۋە ئىككى بالىسى بار.","u alliburun toy qilghan we ikki balisi bar."]],"已婚已育":[["他已婚已育，生活稳定。","ئۇ ئاللىبۇرۇن توي قىلغان ۋە بالىلىق، تۇرمۇشى مۇقىم.","u alliburun toy qilghan we baliliq, turmushi muqim."]],"巴三览四":[["他巴三览四，毫无耐心。","ئۇ ھەر يەرنى ئارىلاپ، ھېچقانداق سەۋر-تاقىتى يوق.","u her yerni arilap, héchqandaq sewr-taqiti yoq."]],"己方":[["己方在谈判中提出了新方案。","ئۆز تەرەپ سۆز سۆزلەشتە يېڭى پىلاننى ئوتتۇرىغا قويدى.","öz terep söz sözleshte yéngi pilanni otturigha qoydi."]],"巴东":[["巴东位于湖北省。","بادوڭ خۇبېي ئۆلكىسىدە جايلاشقان.","badong xubéy ölkiside jaylashqan."]],"巴格兰":[["巴格兰是阿富汗城市。","باغلان ئافغانىستاننىڭ بىر شەھىرى.","baghlan afghanistanning bir shehiri."]],"市政厅":[["市政厅是政府处理公共事务的机构。","شەھەر ھۆكۈمەت سارىيى ھۆكۈمەتنىڭ ئاممىۋى ئىشلارنى بىر تەرەپ قىلىدىغان ئورگىنىدۇر.","sheher hökümet sariyi hökümetning ammiwi ishlarni bir terep qilidighan orginidur."]],"布下":[["将军在战场布下重重陷阱。","گېنېرال جەڭ مەيدانىدا قاتمۇ-قات تۇزاق قۇردى.","général jeng meydanida qatmu-qat tuzaq qurdi."]],"布莱叶":[["布莱叶创造了盲文，造福了盲人。","برايېل كورلار يېزىقىنى ئىجاد قىلىپ، كورلارغا مەنپەئەت يەتكۈزدى.","brayél korlar yéziqini ijad qilip, korlargha menpeet yetküzdi."]],"布袋":[["这个布袋装满了礼物。","بۇ بۇز خالتا سوۋغاتلار بىلەن تولغان.","bu buz xalta sowghatlar bilen tolghan."]],"布鞋":[["布鞋是一种传统的中国手工鞋。","بۇخەن جۇڭگونىڭ ئەنئەنىۋى قول ھۈنەرۋەنچىلىك ئايىغىدۇر.","buxen junggoning en'eniwi qol hünerwenchilik ayighidur."]],"布鲁克林大桥":[["布鲁克林大桥是纽约的标志性建筑。","برۇكلىن كۆۋرۈكى نيۇيوركنىڭ سىمۋوللۇق بىناسىدۇر.","bruklin köwrüki nyuyorkning simwolluq binasidur."]],"平板电脑":[["平板电脑可以替代传统笔记本，操作更便捷。","تەكشى تاختىلىق كومپيۇتېر ئەنئەنىۋى نوتبۇكنىڭ ئورنىنى ئالالايدۇ، مەشغۇلاتى تېخىمۇ قولايلىق.","tekshi taxtiliq kompyutér en'eniwi notbukning ornini alalaydu, meshghulati téximu qolayliq."]],"底夸克":[["底夸克是基本粒子。","ئاستى كۋاركى ئاساسىي زەررىچە.","asti kwarki asasiy zerriche."]],"幽雅":[["她的举止优雅而幽雅。","ئۇنىڭ ئەخلاق-ئەدەبى ناھايىتى نەپىس ۋە ئېلىپسىمان.","uning exlaq-edebi nahayiti nepis we élipsiman."]],"幻境":[["这个幻境美得令人难以置信。","بۇ خىيالىي دۇنيا گۈزەللىكى ئىشەنگۈسىز دەرىجىدە.","bu xiyaliy dunya güzelliki ishengüsiz derijide."]],"康多莉扎·赖斯":[["康多莉扎·赖斯曾任美国国务卿。","كوندولىزا رایس ئامېرىكىنىڭ دۆلەت كاتىپى بولۇپ ئىشلىگەن.","kondoliza rays amérikining dölet katipi bolup ishligen."]],"康巴藏区":[["康巴藏区风景壮丽。","كانڭبا تىبەت رايونىنىڭ مەنزىرىسى ھەيۋەتلىك.","kanngba tibet rayonining menzirisi heywetlik."]],"平桥区":[["平桥区位于城市的北部。","پىڭچياۋ رايونى شەھەرنىڭ شىمالىدا جايلاشقان.","pingchyaw rayoni sheherning shimalida jaylashqan."]],"康县":[["康县是甘肃省的一个山区县。","كاڭ ناھىيىسى گەنسۇ ئۆلكىسىدىكى بىر تاغلىق ناھىيە.","kang nahiyisi gensu ölkisidiki bir taghliq nahiye."]],"广西壮族自治区":[["广西壮族自治区首府是南宁。","گۇاڭشى جۇاڭزۇ ئاپتونوم رايونىنىڭ مەركىزى نەننىڭدۇر.","guangshi juangzu aptonom rayonining merkizi nenningdur."]],"张德江":[["张德江是中国共产党的领导人。","جاڭ دېجياڭ جۇڭگو كوممۇنىستىك پارتىيەسىنىڭ رەھبىرى.","jang déjyang junggo kommunistik partiyesining rehbiri."]],"张荫桓":[["张荫桓是晚清的政治家。","جاڭ يىنخۇەن چىڭ سۇلالىسىنىڭ ئاخىرقى مەزگىلىدىكى سىياسەتچى.","jang yinxuen ching sulalisining axirqi mezgilidiki siyasetchi."]],"弱项":[["英语是他的弱项，需要加强练习。","ئىنگلىز تىلى ئۇنىڭ ئاجىز تەرىپى، مەشىقنى كۈچەيتىش كېرەك.","ingliz tili uning ajiz teripi, meshiqni kücheytish kérek."]],"彼一时此一时":[["彼一时此一时，情况已不同。","ئۇ چاغ باشقا، بۇ چاغ باشقا، ئەھۋال ئاللىبۇرۇن ئۆزگەردى.","u chagh bashqa, bu chagh bashqa, ehwal alliburun özgerdi."]],"后院起火":[["公司后院起火，出现了内乱。","شىركەتنىڭ ئارقا ھويلىسىدا ئوت چىقىپ، ئىچكى قالايمىقانچىلىق كۆرۈلدى.","shirketning arqa hoylisida ot chiqip, ichki qalaymiqanchiliq körüldi."]],"从父":[["孩子随父姓，称为从父。","بالا دادىسىنىڭ فامىلىسىنى ئالىدۇ، بۇ ئاتا تەرەپ دەپ ئاتىلىدۇ.","bala dadisining familisini alidu, bu ata terep dep atilidu."]],"后父":[["后父待我如亲生儿子。","ئۆگەي ئاتا مېنى ئۆز ئوغلۇمدەك كۆردى.","ögey ata méni öz oghlumdek kördi."]],"微胖":[["微胖的身材显得健康又可爱。","مىكرو تومپاي گەۋدە ساغلام ۋە يېقىملىق كۆرۈنىدۇ.","mikro tompay gewde saghlam we yéqimliq körünidu."]],"思春":[["青少年进入思春期后情绪多变。","ياشلار بالاغەت يېشىغا كىرگەندىن كېيىن كەيپىياتى ئۆزگىرىشچان بولىدۇ.","yashlar balaghet yéshigha kirgendin kéyin keypiyati özgirishchan bolidu."]],"心律":[["正常的心律是每分钟60到100次。","نورمال يۈرەك رىتىمى ھەر مىنۇتتا 60 تىن 100 گىچە.","normal yürek ritimi her minutta 60 tin 100 giche."]],"心下":[["他心下有些不安。","ئۇنىڭ كۆڭلىدە ئازراق بىئاراملىق بار.","uning könglide azraq biaramliq bar."]],"恩爱":[["夫妻二人恩爱有加，令人羡慕。","ئەر-خوتۇن ئىككىسى مېھىر-مۇھەببەتتە ئاشقان بولۇپ، كىشىنى ھەۋەس قىلدۇرىدۇ.","er-xotun ikkisi méhir-muhebbette ashqan bolup, kishini hewes qilduridu."]],"心神恍惚":[["他心神恍惚，记不清事情。","ئۇنىڭ روھى چاچراپ، ئىشلارنى ئېنىق ئېسىغا ئالالمايدۇ.","uning rohi chachrap, ishlarni éniq ésigha alalmaydu."]],"急袭":[["敌军发动了急袭，打我们个措手不及。","دۈشمەن تۇيۇقسىز ھۇجۇم قوزغاپ، بىزنى تەييارلىقسىز قالدۇردى.","düshmen tuyuqsiz hujum qozghap, bizni teyyarliqsiz qaldurdi."]],"急转弯":[["汽车急转弯，差点撞上了行人。","ماشىنا جىددىي بۇرۇلۇپ، پىيادىلەرگە سوقۇلۇپ كەتكىلى تاس قالدى.","mashina jiddiy burulup, piyadilerge soqulup ketkili tas qaldi."]],"愚公移山":[["愚公移山的故事激励了无数人。","ئەخمىق بوۋا تاغنى يۆتكەش ھېكايىسى سان-سىقىمسىز كىشىلەرنى رىغبەتلەندۈردى.","exmiq bowa taghni yötkesh hékayisi san-siqimsiz kishilerni righbetlendürdi."]],"意气风发":[["他意气风发地走上了舞台。","ئۇ روھىي جەھەتتىن ئۇرغۇپ، سەھنىگە چىقتى.","u rohiy jehettin urghup, sehnige chiqti."]],"悟性":[["他的悟性极高，一点就通。","ئۇنىڭ چۈشىنىش قابىلىيىتى ئىنتايىن يۇقىرى، ئازغىنا ئىشارەت بىلەنلا چۈشىنىپ قالدى.","uning chüshinish qabiliyiti intayin yuqiri, azghina isharet bilenla chüshinip qaldi."]],"爱德华":[["爱德华是一位伟大的科学家。","ئېدۋارد ئۇلۇغ ئالىم.","édward ulugh alim."]],"慕丝":[["慕丝是一种柔软的织物。","مۇسس بىر خىل يۇمشاق رەخت.","muss bir xil yumshaq rext."]],"凭陵":[["不可凭陵他人。","باشقىلارغا زوراۋانلىق قىلىشقا بولمايدۇ.","bashqilargha zorawanliq qilishqa bolmaydu."]],"惯偷":[["惯偷屡次作案，终被抓获。","ئادەتلەنگەن ئوغرى قايتا-قايتا جىنايەت سادىر قىلىپ، ئاخىرى تۇتۇلدى.","adetlengen oghri qayta-qayta jinayet sadir qilip, axiri tutuldi."]],"应机立断":[["他应机立断解决了问题。","ئۇ پۇرسەتنى چىڭ تۇتۇپ دەرھال قارار چىقىرىپ مەسىلىنى ھەل قىلدى.","u pursetni ching tutup derhal qarar chiqirip mesilini hel qildi."]],"憨子":[["那个憨子总是笑呵呵的。","ئۇ ساددا كىشى ھەمىشە كۈلۈمسىرەپ تۇرىدۇ.","u sadda kishi hemishe külümsirep turidu."]],"怀恨":[["他因被误解而怀恨在心。","ئۇ خاتا چۈشىنىلگەنلىكى ئۈچۈن ئىچىدە ئۆچمەنلىك ساقلىدى.","u xata chüshinilgenliki üchün ichide öchmenlik saqlidi."]],"懒人":[["这个懒人总爱赖床。","بۇ يالغاۋۇك ھەمىشە كارىۋاتتا يېتىشنى ياخشى كۆرىدۇ.","bu yalghawuk hemishe kariwatta yétishni yaxshi köridu."]],"怀表":[["这块怀表是祖传下来的。","بۇ خۇەيبيياۋ ئاتا-بوۋىلاردىن مىراس قالغان.","bu xueybyyaw ata-bowilardin miras qalghan."]],"成品油":[["成品油价格持续上涨。","تەييار ماي باھاسى داۋاملىق ئۆسمەكتە.","teyyar may bahasi dawamliq ösmekte."]],"憎恶":[["她对这种冷漠无情的行为感到深深的憎恶。","ئۇ بۇ سوغۇق قەلبلىق ۋە رەھىمسىزلىك قىلمىشتىن چوڭقۇر نەپرەتلىنىدۇ.","u bu soghuq qelbliq we rehimsizlik qilmishtin chongqur nepretlinidu."]],"戴胜":[["戴胜是一种美丽的鸟类。","دىئوخۇڭ گۈزەل بىر قۇش تۈرىدۇر.","dioxung güzel bir qush türidur."]],"房山区":[["房山区发展迅速，交通便利。","فاڭشەن رايونى تېز تەرەققىي قىلماقتا، قاتناش قۇلاي.","fangshen rayoni téz tereqqiy qilmaqta, qatnash qulay."]],"户县":[["户县是陕西历史悠久的一个县城。","خۇشيەن شەنشىنىڭ ئۇزۇن تارىخقا ئىگە بىر ناھىيىلىك شەھىرى.","xushyen shenshining uzun tarixqa ige bir nahiyilik shehiri."]],"所罗门群岛":[["所罗门群岛是太平洋上的国家。","سۇلەيمان تاقىم ئاراللىرى تىنچ ئوكياندىكى بىر دۆلەتتۇر.","suleyman taqim aralliri tinch okyandiki bir dölettur."]],"所部":[["所部军队在战斗中表现出色。","قوشۇننىڭ بىر قىسمى جەڭدە ئالاھىدە ياخشى ئىپادىلەندى.","qoshunning bir qismi jengde alahide yaxshi ipadilendi."]],"手摇柄":[["手摇柄的设计让操作更省力。","قول بىلەن ئايلاندۇرىدىغان دەستىنىڭ لايىھەسى مەشغۇلاتنى تېخىمۇ كۈچ تەلەپ قىلمايدىغان قىلىدۇ.","qol bilen aylanduridighan destining layihesi meshghulatni téximu küch telep qilmaydighan qilidu."]],"打瞌睡":[["他在会议中忍不住打瞌睡。","ئۇ يىغىندا ئۆزىنى تۇتۇۋالالماي ئۇخلاپ قالدى.","u yighinda özini tutuwalalmay uxlap qaldi."]],"托克逊县":[["托克逊县以葡萄闻名。","توقسۇن ناھىيىسى ئۈزۈمى بىلەن داڭلىق.","toqsun nahiyisi üzümi bilen dangliq."]],"打开天窗说亮话":[["我们打开天窗说亮话吧。","ئوچۇق ئېيتايلى، ئېنىق سۆزلەيلى.","ochuq éytayli, éniq sözleyli."]],"折刀":[["他随身携带一把小巧的折刀。","ئۇ ئۆزى بىلەن بىر دانە كىچىك قاتلىما پىچاق ئېلىپ يۈرىدۇ.","u özi bilen bir dane kichik qatlima pichaq élip yüridu."]],"承认控罪":[["被告承认控罪并请求宽大处理。","جاۋابكار ئەيىبلەشكە ئىقرار بولدى ۋە كەڭچىلىك سورىدى.","jawabkar eyibleshke iqrar boldi we kengchilik soridi."]],"抗凝血剂":[["抗凝血剂常用于预防血栓形成的医疗中。","قان ئۇيۇشۇشقا قارشى دورىلار كۆپىنچە قان تومۇر ئېتىلىشىنىڭ ئالدىنى ئېلىش داۋالىنىشىدا ئىشلىتىلىدۇ.","qan uyushushqa qarshi dorilar köpinche qan tomur étilishining aldini élish dawalinishida ishlitilidu."]],"抗原":[["这种病毒会产生特定的抗原。","بۇ خىل ۋىرۇس ئالاھىدە ئانتىگېن ئىشلەپ چىقىرىدۇ.","bu xil wirus alahide antigén ishlep chiqiridu."]],"抗抑郁药":[["抗抑郁药能改善情绪障碍。","غەمكىنلىككە قارشى دورىلار كەيپىيات بۇزۇلۇشىنى ياخشىلىيالايدۇ.","ghemkinlikke qarshi dorilar keypiyat buzulushini yaxshiliyalaydu."]],"拌嘴":[["他们经常拌嘴。","ئۇلار دائىم ئاغىز ئېچىشىپ قالىدۇ.","ular daim aghiz échiship qalidu."]],"拉斯帕尔马斯":[["拉斯帕尔马斯是西班牙城市。","لاس پالماس ئىسپانىيە شەھىرى.","las palmas ispaniye shehiri."]],"拖链":[["拖链用于连接机械设备的部件。","سۆرەش زەنجىرى مېخانىكىلىق ئۈسكۈنىلەرنىڭ زاپچاسلىرىنى ئۇلاشقا ئىشلىتىلىدۇ.","söresh zenjiri méxanikiliq üskünilerning zapchaslirini ulashqa ishlitilidu."]],"拘检":[["官员进行拘检行动。","ئەمەلدارلار چەكلەش تەكشۈرۈش ھەرىكىتىنى ئېلىپ باردى.","emeldarlar cheklesh tekshürüsh herikitini élip bardi."]],"拱点":[["这个拱点是整个结构的关键支撑。","بۇ گۈمبەز نۇقتىسى پۈتۈن قۇرۇلمىنىڭ مۇھىم تىرىكى.","bu gümbez nuqtisi pütün qurulmining muhim tiriki."]],"拳击":[["拳击是一项考验力量和技巧的运动。","بوكس كۈچ ۋە ماھارەتنى سىنايدىغان بىر تەنتەربىيە تۈرى.","boks küch we maharetni sinaydighan bir tenterbiye türi."]],"指鹿作马":[["他公然指鹿作马，混淆视听。","ئۇ ئوچۇق-ئاشكارا كىيىكنى ئات قىلىپ، كۆز-قۇلاقنى قالايمىقانلاشتۇردى.","u ochuq-ashkara kiyikni at qilip, köz-qulaqni qalaymiqanlashturdi."]],"捧杯":[["她优雅地捧杯敬酒，笑容灿烂。","ئۇ نەپىس ھالدا جامنى كۆتۈرۈپ ھاراق ئىچتى، كۈلۈمسىرىشى پارلاق ئىدى.","u nepis halda jamni kötürüp haraq ichti, külümsirishi parlaq idi."]],"掉向":[["卫星掉向预定轨道。","سۈنئىي ھەمراھ مۇئەييەن ئوربىتىغا چۈشۈۋاتىدۇ.","sün'iy hemrah mueyyen orbitigha chüshüwatidu."]],"排空":[["排空操作可确保设备正常运行。","بوشىتىش مەشغۇلاتى ئۈسكۈنىنىڭ نورمال ئىشلىشىنى كاپالەتكە ئىگە قىلالايدۇ.","boshitish meshghulati üskünining normal ishlishini kapaletke ige qilalaydu."]],"排骨精":[["她瘦得像排骨精。","ئۇ شورپا سۆڭىكىدەك ئورۇقلاپ كەتكەن.","u shorpa söngikidek oruqlap ketken."]],"揄扬":[["文章揄扬了英雄事迹。","ماقالە قەھرىمانلارنىڭ ئىشلىرىنى مەدھىيىلىدى.","maqale qehrimanlarning ishlirini medhiyilidi."]],"提克里特":[["提克里特是古代美索不达米亚的城市。","تىكرىت قەدىمكى مېسوپوتامىيەدىكى بىر شەھەر.","tikrit qedimki mésopotamiyediki bir sheher."]],"扬帆远航":[["我们扬帆远航，开启新的旅程。","بىز يەلكەن كۆتۈرۈپ ئۇزۇن سەپەرگە ئاتلىنىپ، يېڭى سەپەرنى باشلىدۇق.","biz yelken kötürüp uzun seperge atlinip, yéngi seperni bashliduq."]],"搬石头砸自己的脚":[["搬石头砸自己的脚。","ئۆز پۇتىغا تاش ئېتىپ ئۆزىنى زەخىملەندۈردى.","öz putigha tash étip özini zeximlendürdi."]],"摸不着头脑":[["他听了半天，还是摸不着头脑。","ئۇ ئۇزۇن ۋاقىت ئاڭلىدى، ئەمما يەنىلا كاللىسىگە كەلمىدى.","u uzun waqit anglidi, emma yenila kallisige kelmidi."]],"捞一把":[["他想捞一把好处。","ئۇ بىر پارچە پايدا ئېلىشنى خالىدى.","u bir parche payda élishni xalidi."]],"击溃":[["我军击溃了敌人的进攻。","بىزنىڭ ئارمىيە دۈشمەننىڭ ھۇجۇمىنى تارمار قىلدى.","bizning armiye düshmenning hujumini tarmar qildi."]],"击球":[["他用力击球，得分了。","ئۇ توپنى قاتتىق ئۇرۇپ نومۇر ئالدى.","u topni qattiq urup nomur aldi."]],"撒手闭眼":[["他安详地撒手闭眼。","ئۇ تىنچ ھالدا كۆزىنى يۇمۇپ جان ئۈزدى.","u tinch halda közini yumup jan üzdi."]],"择善固执":[["他坚持择善固执。","ئۇ ياخشىلىقنى تۇتۇپ چىڭ تۇردى.","u yaxshiliqni tutup ching turdi."]],"击弦类乐器":[["吉他属于击弦类乐器。","گىتار چەكلىك ساز ئەسۋابلىرى قاتارىغا كىرىدۇ.","gitar cheklik saz eswabliri qatarigha kiridu."]],"拨子":[["他用拨子弹奏古筝。","ئۇ پىپا بىلەن گۇجېڭ چالدى.","u pipa bilen gujéng chaldi."]],"扰攘":[["市场里一片扰攘喧闹。","بازاردا قالايمىقانچىلىق ۋە شاۋقۇن-سۈرەن بار ئىدى.","bazarda qalaymiqanchiliq we shawqun-süren bar idi."]],"攻心":[["心理战旨在攻心夺志。","پسىخولوگىيەلىك ئۇرۇش قەلبنى ئىگىلەش ۋە ئىرادىنى يوقىتىشنى مەقسەت قىلىدۇ.","psixologiyelik urush qelbni igilesh we iradini yoqitishni meqset qilidu."]],"教务":[["教务工作繁忙。","وقۇغۇچىلار ئىشلىرى خىزمىتى ئالدىراش.","oqughuchilar ishliri xizmiti aldirash."]],"教条":[["这些教条束缚了人们的思想。","بۇ دوگمىلار كىشىلەرنىڭ ئىدىيەسىنى چەكلەيدۇ.","bu dogmilar kishilerning idiyesini chekleydu."]],"敬虔":[["他敬虔地祈祷。","ئۇ تەقۋادارلىق بىلەن دۇئا قىلدى.","u teqwadarliq bilen dua qildi."]],"文本编辑器":[["文本编辑器支持多种格式。","تېكىست تەھرىرلىگۈچ كۆپ خىل فورماتلارنى قوللايدۇ.","tékist tehrirligüch köp xil formatlarni qollaydu."]],"斑背大尾莺":[["斑背大尾莺的尾巴格外修长。","تاغ تېكىسى چوڭ قۇيرۇق قۇشىنىڭ قۇيرۇقى ئالاھىدە ئۇزۇن.","tagh tékisi chong quyruq qushining quyruqi alahide uzun."]],"斜径":[["穿过森林的斜径十分隐蔽。","ئورمان ئىچىدىن ئۆتىدىغان يانتاي يول ئىنتايىن يوشۇرۇن.","orman ichidin ötidighan yantay yol intayin yoshurun."]],"数量级":[["这个数的数量级是十的八次方。","بۇ ساننىڭ تەرتىپ چوڭلۇقى ئوننىڭ سەككىزىنچى دەرىجىسىگە تەڭ.","bu sanning tertip chongluqi onning sekkizinchi derijisige teng."]],"新民主主义":[["新民主主义是中国革命的重要理论。","يېڭى دېموكراتىزم جۇڭگو ئىنقىلابىنىڭ مۇھىم نەزەرىيىسى.","yéngi démokratizm junggo inqilabining muhim nezeriyisi."]],"新市区":[["新市区是城市的核心区域。","شىنشى رايونى شەھەرنىڭ يادرولۇق رايونى.","shinshi rayoni sheherning yadroluq rayoni."]],"施主能级":[["施主能级是物理学中的概念。","ئىگە ئېنېرگىيە سەۋىيىسى فىزىكىدىكى بىر ئۇقۇمدۇر.","ige énérgiye sewiyisi fizikidiki bir uqumdur."]],"日中":[["日中两国正在加强经济合作。","ياپونىيە بىلەن جۇڭگو ئىقتىسادىي ھەمكارلىقنى كۈچەيتىۋاتىدۇ.","yaponiye bilen junggo iqtisadiy hemkarliqni kücheytiwatidu."]],"旺炽型":[["这款旺炽型设备性能卓越。","بۇ ۋاڭچى تىپلىق ئۈسكۈنىنىڭ ئىقتىدارى ئالاھىدە يۇقىرى.","bu wangchi tipliq üskünining iqtidari alahide yuqiri."]],"旬朔":[["旬朔指每月的前十天。","شۈنشو ھەر ئاينىڭ ئالدىنقى ئون كۈنىنى كۆرسىتىدۇ.","shünsho her ayning aldinqi on künini körsitidu."]],"明胶":[["明胶常用于制作果冻和糖果。","جېلاتىن كۆپىنچە مېۋە-چېۋە قەنت ۋە كەمپۈت ياساشتا ئىشلىتىلىدۇ.","jélatin köpinche méwe-chéwe qent we kempüt yasashta ishlitilidu."]],"易腐败":[["食物放置太久容易腐败。","ئوزۇقلۇقنى ئۇزۇن ۋاقىت ساقلىغاندا ئاسان بۇزۇلىدۇ.","ozuqluqni uzun waqit saqlighanda asan buzulidu."]],"春播":[["春播关系到全年的收成。","باھار تېرىقچىلىقى پۈتۈن يىللىق ھوسۇل بىلەن مۇناسىۋەتلىك.","bahar tériqchiliqi pütün yilliq hosul bilen munasiwetlik."]],"星座":[["每个星座都有独特的神话故事。","ھەر بىر يۇلتۇزلار تۈركۈمىنىڭ ئۆزىگە خاس ئەپسانىۋى ھېكايىسى بار.","her bir yultuzlar türkümining özige xas epsaniwi hékayisi bar."]],"普陀区":[["普陀区位于上海市中心。","پۇتو رايونى شاڭخەي شەھىرىنىڭ مەركىزىدە جايلاشقان.","puto rayoni shangxey shehirining merkizide jaylashqan."]],"普世":[["普世价值观受到广泛认可。","ئۇمۇمىي قىممەت قاراشلىرى كەڭ دائىرىدە ئېتىراپ قىلىنىدۇ.","umumiy qimmet qarashliri keng dairide étirap qilinidu."]],"普世基督教":[["普世基督教强调全球信徒的团结。","ئۇمۇمىي خىرىستىيانلىق دۇنيادىكى مۇئمىنلەرنىڭ بىرلىكىنى تەكىتلەيدۇ.","umumiy xiristiyanliq dunyadiki muminlerning birlikini tekitleydu."]],"景谷":[["景谷是云南省的一个县。","جىڭگۇ يۇننەن ئۆلكىسىدىكى بىر ناھىيەدۇر.","jinggu yunnen ölkisidiki bir nahiyedur."]],"有效性":[["实验结果验证了其有效性。","تەجرىبە نەتىجىسى ئۇنىڭ ئۈنۈملۈكلۈكىنى ئىسپاتلىدى.","tejribe netijisi uning ünümlüklükini ispatlidi."]],"有新意":[["这个设计很有新意。","بۇ لايىھە ئىنتايىن يېڭىلىقچان.","bu layihe intayin yéngiliqchan."]],"会堂":[["会议在大型会堂举行。","يىغىن چوڭ يىغىن زالىدا ئۆتكۈزۈلدى.","yighin chong yighin zalida ötküzüldi."]],"朋友圈":[["她经常在朋友圈分享生活。","ئۇ دائىم دوستلار چەمبىرىكىدە تۇرمۇشىنى ئورتاقلىشىدۇ.","u daim dostlar chembirikide turmushini ortaqlishidu."]],"朗吟":[["他朗吟着古诗，充满激情。","ئۇ قەدىمكى شېئىرلارنى ئاۋاز قوشۇپ ئوقۇيدۇ، ھېسسىياتقا تولغان.","u qedimki shéirlarni awaz qoshup oquydu, héssiyatqa tolghan."]],"服法":[["请按照说明正确服法。","دورىنى ئىشلىتىش ئۇسۇلى بويىچە توغرا ئىشلىتىڭ.","dorini ishlitish usuli boyiche toghra ishliting."]],"服装秀":[["这场服装秀展示了最新的时尚潮流。","بۇ كىيىم-كېچەك نامىيىشى ئەڭ يېڭى مودا ئېقىمىنى نامايان قىلدى.","bu kiyim-kéchek namiyishi eng yéngi moda éqimini namayan qildi."]],"有本事":[["你有本事就试试看！","ئىقتىدارىڭ بولسا سىناپ باققىن!","iqtidaring bolsa sinap baqqin!"]],"有核国家":[["有核国家必须承担责任。","يادرو قوراللىرىغا ئىگە دۆلەتلەر مەسئۇلىيەت ئۈستىگە ئېلىشى كېرەك.","yadro qorallirigha ige döletler mes'uliyet üstige élishi kérek."]],"木华黎":[["木华黎是历史上著名的将领。","موخۇلى تارىختا ئاتاقلىق سەركەردە ئىدى.","moxuli tarixta ataqliq serkerde idi."]],"木屐":[["她穿着木屐走在石板路上。","ئۇ ياغاچ كەشى بىلەن تاش يولدا ماڭدى.","u yaghach keshi bilen tash yolda mangdi."]],"李冶":[["李冶的诗歌充满浪漫情怀。","لى يېنىڭ شېئىرلىرى رومانتىك ھېسسىياتقا تولغان.","li yéning shéirliri romantik héssiyatqa tolghan."]],"本应":[["本应如此，但实际情况却不同。","ئەسلىدە شۇنداق بولۇشى كېرەك ئىدى، ئەمما ئەمەلىي ئەھۋال باشقىچە بولدى.","eslide shundaq bolushi kérek idi, emma emeliy ehwal bashqiche boldi."]],"李振藩":[["李振藩以功夫闻名世界。","لى جېنفەن كۇڭفۇ بىلەن دۇنياغا مەشھۇر.","li jénfen kungfu bilen dunyagha meshhur."]],"朱古力":[["朱古力是孩子们最喜欢的零食之一。","شوكولات كىچىك بالىلارنىڭ ئەڭ ياخشى كۆرىدىغان يېمەكلىكلىرىنىڭ بىرى.","shokolat kichik balilarning eng yaxshi köridighan yémekliklirining biri."]],"朱熹":[["朱熹是南宋时期著名的思想家。","جۇ شى جەنۇبىي سۇڭ دەۋرىنىڭ تانىلغان مۇتەپەككۇرى.","ju shi jenubiy sung dewrining tanilghan mutepekkuri."]],"杏林":[["杏林常用来比喻医学界。","ئۆرۈكزار ئادەتتە تېببىيەت دۇنياسىنى سېلىشتۇرۇشقا ئىشلىتىلىدۇ.","örükzar adette tébbiyet dunyasini sélishturushqa ishlitilidu."]],"杜甫草堂":[["杜甫草堂位于成都。","دۇفۇ چىسەڭ چېڭدۇدا.","dufu chiseng chéngduda."]],"林怀民":[["林怀民是台湾现代舞的开创者。","لىن خۇەيمىن تەيۋەن زامانىۋى ئۇسسۇلىنىڭ ئاساسچىسى.","lin xueymin teywen zamaniwi ussulining asaschisi."]],"朽木不可雕":[["朽木不可雕，比喻无药可救。","چىرىگەن ياغاچنى ئويۇپ ئىشلەتكىلى بولمايدۇ، بۇ دورىسىز قۇتۇلمايدىغانلىققا ئوخشايدۇ.","chirigen yaghachni oyup ishletkili bolmaydu, bu dorisiz qutulmaydighanliqqa oxshaydu."]],"枷板":[["枷板是刑具的一部分。","كىشەن تاختىسى جازا قورالىنىڭ بىر قىسمىدۇر.","kishen taxtisi jaza qoralining bir qismidur."]],"核素":[["每种核素都具有独特的放射性。","ھەر بىر نۇكلېئىد ئۆزىگە خاس رادىيوئاكتىپلىققا ئىگە.","her bir nukléid özige xas radiyoaktipliqqa ige."]],"格萨尔":[["格萨尔是一位著名的藏族英雄。","گېسار ئاتاقلىق تىبەت قەھرىمانى.","gésar ataqliq tibet qehrimani."]],"梅里斯":[["梅里斯是加拿大阿尔伯塔省的一座城市。","مېيرىس كانادا ئالبېرتا ئۆلكىسىدىكى بىر شەھەر.","méyris kanada albérta ölkisidiki bir sheher."]],"枣强县":[["枣强县以枣树闻名全国。","زاۋچياڭ ناھىيىسى چىلان دەرەخلىرى بىلەن پۈتۈن مەملىكەتكە تونۇلغان.","zawchyang nahiyisi chilan derexliri bilen pütün memliketke tonulghan."]],"植物群":[["这里的植物群非常丰富多样。","بۇ يەردىكى ئۆسۈملۈكلەر توپى ئىنتايىن مول ۋە خىلمۇخىلدۇر.","bu yerdiki ösümlükler topi intayin mol we xilmuxildur."]],"杨虎城":[["杨虎城是近代中国的重要历史人物。","ياڭ خۇچېڭ يېقىنقى زامان جۇڭگونىڭ مۇھىم تارىخىي شەخسى.","yang xuchéng yéqinqi zaman junggoning muhim tarixiy shexsi."]],"杨锐":[["杨锐是清末民初的革命志士和思想家。","ياڭ رۇي چىڭ سۇلالىسىنىڭ ئاخىرى ۋە جۇڭخۇا جۇمھۇرىيىتىنىڭ باشلىنىشىدىكى ئىنقىلابچى ۋە مۇتەپەككۇر.","yang ruy ching sulalisining axiri we jungxua jumhuriyitining bashlinishidiki inqilabchi we mutepekkur."]],"极光":[["北极光在夜空中呈现出绿色和紫色。","شىمالىي قۇتۇپ نۇرى كېچە ئاسمىنىدا يېشىل ۋە بىنەپشە رەڭدە كۆرۈنىدۇ.","shimaliy qutup nuri kéche asminida yéshil we binepshe rengde körünidu."]],"梧桐科":[["梧桐属于梧桐科植物。","ۋۇتونگ ۋۇتونگ ئائىلىسىگە تەۋە ئۆسۈملۈكتۇر.","wutong wutong ailisige tewe ösümlüktur."]],"梨子":[["梨子是一种常见的水果。","نەشپۈت كۆپ ئۇچرايدىغان بىر خىل مېۋىدۇر.","neshpüt köp uchraydighan bir xil méwidur."]],"概念验证":[["实验完成了概念验证环节。","تەجرىبە ئۇقۇم ئىسپاتلاش باسقۇچىنى تاماملىدى.","tejribe uqum ispatlash basquchini tamamlidi."]],"树蛙":[["树蛙善于在树上跳跃。","دەرەخ پاقىسى دەرەخلەردە چاقچاق ئويناشقا ماھىر.","derex paqisi derexlerde chaqchaq oynashqa mahir."]],"桦川县":[["桦川县历史悠久。","خۇاچۇان ناھىيىسىنىڭ تارىخى ئۇزۇن.","xuachuan nahiyisining tarixi uzun."]],"检票":[["检票员仔细核对每位乘客的票证。","بېلەت تەكشۈرگۈچى ھەر بىر يولۇچىنىڭ بېلىتىنى ئەستايىدىل تەكشۈردى.","bélet tekshürgüchi her bir yoluchining bélitini estayidil tekshürdi."]],"枪筒":[["枪筒里残留着未完全燃烧的弹壳。","مىلتىقنىڭ ئىچىدە تولۇق يانمىغان گىلۇزە قالدۇقى بار.","miltiqning ichide toluq yanmighan giluze qalduqi bar."]],"欲言又止":[["他欲言又止，不知如何开口。","ئۇ سۆزلەمەكچى بولۇپ ئىككىلەندى، قانداق باشلاشنى بىلمىدى.","u sözlemekchi bolup ikkilendi, qandaq bashlashni bilmidi."]],"歇了吧":[["别干了，歇了吧！","ئىشلەشنى قوي، ئارام ئالغىن!","ishleshni qoy, aram alghin!"]],"权谋":[["权谋之术深不可测。","ھىيلە-مىكىر ئۇسۇللىرى چوڭقۇر ۋە چەكسىز.","hiyle-mikir usulliri chongqur we cheksiz."]],"武城":[["武城是古代的一座重要城池。","ۋۇچېڭ قەدىمكى زاماندىكى مۇھىم بىر شەھەر ئىدى.","wuchéng qedimki zamandiki muhim bir sheher idi."]],"武川县":[["武川县以草原风光著称。","ۋۇچۈەن ناھىيىسى يايلاق مەنزىرىسى بىلەن تونۇلغان.","wuchüen nahiyisi yaylaq menzirisi bilen tonulghan."]],"步进马达":[["步进马达能精确控制旋转角度。","قەدەملىك ماتور ئايلىنىش بۇلۇڭىنى ئېنىق كونترول قىلالايدۇ.","qedemlik mator aylinish bulungini éniq kontrol qilalaydu."]],"死心":[["她终于对这段感情死心了。","ئۇ ئاخىرى بۇ مۇھەببەتتىن ئۈمىدسىزلەندى.","u axiri bu muhebbettin ümidsizlendi."]],"正宫娘娘":[["正宫娘娘是皇帝的主要配偶。","جېڭگۇڭ خانىم پادىشاھنىڭ ئاساسلىق جۈپتى ئىدى.","jénggung xanim padishahning asasliq jüpti idi."]],"殊色":[["这片土地有着殊色风光。","بۇ زېمىننىڭ ئالاھىدە مەنزىرىسى بار.","bu zéminning alahide menzirisi bar."]],"杀人案件":[["警方正在调查这起杀人案件。","ساقچىلار بۇ ئۆلتۈرۈش ئىشىنى تەكشۈرمەكتە.","saqchilar bu öltürüsh ishini tekshürmekte."]],"比拼":[["这场比赛是实力的比拼。","بۇ مۇسابىقە كۈچ-قۇدرىتىنىڭ سېلىشتۇرمىسى.","bu musabiqe küch-qudritining sélishturmisi."]],"归顺":[["叛军最终选择归顺朝廷。","ئىسيانچىلار ئاخىرى سارايغا بوي سۇنۇشنى تاللىدى.","isyanchilar axiri saraygha boy sunushni tallidi."]],"毒刺":[["这种昆虫的毒刺能分泌致命毒素。","بۇ خىل ھاشارىتىنىڭ زەھەر قىلىچى ئۆلۈمگە سەۋەب بولىدىغان زەھەر ئاجرىتىپ چىقىرالايدۇ.","bu xil hasharitining zeher qilichi ölümge seweb bolidighan zeher ajritip chiqiralaydu."]],"殿宇":[["古时的殿宇宏伟壮观。","قەدىمكى زاماندىكى سارايلار ھەيۋەتلىك ۋە كۆركەم ئىدى.","qedimki zamandiki saraylar heywetlik we körkem idi."]],"毁掉":[["他不小心把文件毁掉了。","ئۇ سەۋەنسىزلىكتىن ھۆججەتنى بۇزۇۋەتتى.","u sewensizliktin höjjetni buzuwetti."]],"民族社会主义":[["民族社会主义是一种政治理念。","مىللەت سوتسىيالىزمى بىر خىل سىياسىي ئىدىيە.","millet sotsiyalizmi bir xil siyasiy idiye."]],"殚精竭虑":[["领导殚精竭虑工作。","رەھبەر ئەقلىنى ۋە كۈچىنى سەرپ قىلىپ خىزمەت قىلماقتا.","rehber eqlini we küchini serp qilip xizmet qilmaqta."]],"段落":[["这篇文章的段落安排合理。","بۇ ماقالىنىڭ پاراگراف تەرتىپى مۇۋاپىق.","bu maqalining paragraf tertipi muwapiq."]],"气恼":[["被误解后，他显得十分气恼。","خاتا چۈشىنىلگەندىن كېيىن، ئۇ بەك غەزەپلەنگەندەك كۆرۈندى.","xata chüshinilgendin kéyin, u bek ghezeplengendek köründi."]],"气楼":[["气楼是古代建筑的一部分。","ھاۋا بىناسى قەدىمكى بىناچىلىقنىڭ بىر قىسمى.","hawa binasi qedimki binachiliqning bir qismi."]],"毛口":[["毛口是一种传统工艺。","ماۋكۇ بىر خىل ئەنئەنىۋى ھۈنەردۇر.","mawku bir xil en'eniwi hünerdur."]],"求爷爷告奶奶":[["他四处求爷爷告奶奶。","ئۇ ھەر يەردە ئۆزىنىڭ ياردەم سوراپ يۈردى.","u her yerde özining yardem sorap yürdi."]],"气雾免疫":[["气雾免疫技术用于疫苗研发。","ھاۋا تۇمانى ئىممۇنىتېت تېخنىكىسى ۋاكسىنا تەتقىقاتىغا ئىشلىتىلىدۇ.","hawa tumani immunitét téxnikisi waksina tetqiqatigha ishlitilidu."]],"汽锅":[["汽锅菜保留了食材的原汁原味。","بۇغا قازان تاماقلىرى ماتېرىياللارنىڭ ئەسلى تەمىنى ساقلاپ قالغان.","bugha qazan tamaqliri matériyallarning esli temini saqlap qalghan."]],"沙加缅度":[["沙加缅度是美国的著名城市。","ساكرامېنتو ئامېرىكىنىڭ مەشھۇر شەھىرى.","sakraménto amérikining meshhur shehiri."]],"沙堡":[["他用沙子堆了一个沙堡。","ئۇ قۇم بىلەن بىر قۇم قەلئەسى ياسىدى.","u qum bilen bir qum qel'esi yasidi."]],"沙乌地阿拉伯":[["沙乌地阿拉伯是中东的重要国家。","سەئۇدى ئەرەبىستان ئوتتۇرا شەرقنىڭ مۇھىم دۆلىتى.","seudi erebistan ottura sherqning muhim döliti."]],"波莱罗":[["波莱罗是一种舞蹈形式。","بولېرو بىر خىل ئۇسسۇل شەكلى.","boléro bir xil ussul shekli."]],"波罗的海":[["波罗的海是欧洲的内海。","بالتىق دېڭىزى ياۋروپانىڭ ئىچكى دېڭىزى.","baltiq déngizi yawropaning ichki déngizi."]],"泰安乡":[["泰安乡风景优美，适合旅游。","تەيئەن يېزىسىنىڭ مەنزىرىسى گۈزەل، ساياھەتكە ماس كېلىدۇ.","tey'en yézisining menzirisi güzel, sayahetke mas kélidu."]],"洗面乳":[["这款洗面乳很温和。","بۇ يۈز يۇيۇش سۈتى ئىنتايىن يۇمشاق.","bu yüz yuyush süti intayin yumshaq."]],"洗发皂":[["他用洗发皂清洗了头发。","ئۇ چاچ يۇيۇش سوپۇنى بىلەن چېچىنى يۇيدى.","u chach yuyush sopuni bilen chéchini yuydi."]],"洛克西德":[["洛克西德公司研发了新药。","روكخېد شىركىتى يېڭى دورا تەتقىق قىلىپ ياسىدى.","rokxéd shirkiti yéngi dora tetqiq qilip yasidi."]],"洗涤灵":[["这款洗涤灵去污效果强。","بۇ يۇيۇش سۇيۇقلۇقىنىڭ كىر يوقىتىش ئۈنۈمى كۈچلۈك.","bu yuyush suyuqluqining kir yoqitish ünümi küchlük."]],"海勃湾区":[["海勃湾区位于内蒙古的西部。","ھەيبوۋان رايونى ئىچكى موڭغۇلنىڭ غەربىدە جايلاشقان.","heybowan rayoni ichki mongghulning gherbide jaylashqan."]],"浦城":[["浦城历史悠久，文化丰富。","پۇچېڭ ئۇزۇن تارىخقا ئىگە، مەدەنىيىتى مول.","puchéng uzun tarixqa ige, medeniyiti mol."]],"海内外":[["海内外观众对电影反响热烈。","دېڭىز ئىچى ۋە سىرتىدىكى تاماشىبىنلار كىنوغا قىزغىن ئىنكاس قايتۇردى.","déngiz ichi we sirtidiki tamashibinlar kinogha qizghin inkas qayturdi."]],"消化酶":[["消化酶能加速食物分解。","ھەزىم قىلىش فېرمېنتى يېمەكلىكنىڭ پارچىلىنىشىنى تېزلىتەلەيدۇ.","hezim qilish férménti yémeklikning parchilinishini tézliteleydu."]],"消基会":[["消基会致力于保护消费者权益。","ئىستېمالچىلارنىڭ ھوقۇقىنى قوغداش جەمئىيىتى ئىستېمالچىلارنىڭ ھوقۇقىنى قوغداشقا تىرىشىدۇ.","istémalchilarning hoquqini qoghdash jem'iyiti istémalchilarning hoquqini qoghdashqa tirishidu."]],"涉黑":[["警方打击涉黑团伙。","ساقچىلار قارا جەمئىيەتكە چېتىلىدىغان گۇرۇھلارغا زەربە بەردى.","saqchilar qara jem'iyetke chétilidighan guruhlargha zerbe berdi."]],"淋漓":[["雨水从屋檐上淋漓而下，汇成小溪。","يامغۇر ئۆي تۆمۈرىدىن تامچىلاپ چۈشۈپ، كىچىك ئېقىنغا ئايلاندى.","yamghur öy tömüridin tamchilap chüshüp, kichik éqingha aylandi."]],"海西":[["海西地区以独特的自然风光闻名。","خەيشى رايونى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","xeyshi rayoni özgiche tebiiy menzirisi bilen tonulghan."]],"淤灌":[["农田淤灌可以改善土壤结构。","ئېتىز-ئېرىقلارنى لازى بىلەن سۇغىرىش تۇپراق قۇرۇلمىسىنى ياخشىلىيالايدۇ.","étiz-ériqlarni lazi bilen sughirish tupraq qurulmisini yaxshiliyalaydu."]],"消声":[["他调整了设备以消声。","ئۇ ئاۋازنى يوقىتىش ئۈچۈن ئۈسكۈنىنى تەڭشىدى.","u awazni yoqitish üchün üskünini tengshidi."]],"淑静":[["淑静的性格让她在团队中备受信赖和喜爱。","ئۇنىڭ سىلەنچان خاراكتېرى ئۇنى كوماندا ئىچىدە ئىشەنچ ۋە مۇھەببەتكە ئېرىشتۈردى.","uning silenchan xaraktéri uni komanda ichide ishench we muhebbetke érishtürdi."]],"海顿":[["海顿是著名的作曲家。","خەيدۇن مەشھۇر بىر كومپوزىتور.","xeydun meshhur bir kompozitor."]],"温切斯特":[["温切斯特是英国的一个城市。","ۋىنچېستېر ئەنگلىيەدىكى بىر شەھەر.","winchéstér engliyediki bir sheher."]],"溶洞":[["溶洞是石灰岩被水侵蚀形成的。","ئېرىش ئۆڭكۈرى ئاھاك تېشىنىڭ سۇ تەرىپىدىن ئېرىتىلىشىدىن شەكىللەنگەن.","érish öngküri ahak téshining su teripidin éritilishidin shekillengen."]],"滇藏":[["滇藏铁路连接两地。","دىەن-زاڭ تۆمۈريولى ئىككى جايىنى تۇتاشتۇرىدۇ.","dien-zang tömüryoli ikki jayini tutashturidu."]],"滋蔓":[["谣言在人群中迅速滋蔓。","مىش-مىش پاراڭلار ئادەملەر ئارىسىدا تېز تارقالدى.","mish-mish paranglar ademler arisida téz tarqaldi."]],"滑沙":[["滑沙是沙漠中独特的体验。","قۇمدا تېيىلىش چۆلدىكى ئۆزگىچە تەجرىبىدۇر.","qumda téyilish chöldiki özgiche tejribidur."]],"汤姆逊":[["汤姆逊的研究成果令人惊叹。","تومسوننىڭ تەتقىقات نەتىجىلىرى ھەيران قالدۇرىدۇ.","tomsonning tetqiqat netijiliri heyran qalduridu."]],"潜水刀":[["这把潜水刀锋利又轻便。","بۇ سۇ ئاستى پىچىقى ئۆتكۈر ۋە يېنىك.","bu su asti pichiqi ötkür we yénik."]],"渔笼":[["渔笼用于捕捉小型鱼类。","بېلىق قاپقىنى كىچىك بېلىقلارنى تۇتۇشقا ئىشلىتىلىدۇ.","béliq qapqini kichik béliqlarni tutushqa ishlitilidu."]],"潼关县":[["潼关县位于陕西省西南部。","تۇڭگۇەن ناھىيىسى شەنشى ئۆلكىسىنىڭ جەنۇبىي غەربىدە جايلاشقان.","tungguen nahiyisi shenshi ölkisining jenubiy gherbide jaylashqan."]],"渗沟":[["道路旁修建了防涝渗沟。","يول بويىغا سۇ توپلىنىشنىڭ ئالدىنى ئېلىش ئۆستەڭچىسى قۇرۇلدى.","yol boyigha su toplinishning aldini élish östengchisi quruldi."]],"润发乳":[["使用润发乳能让头发更柔顺。","نەملەندۈرۈش چاچ سۈتىنى ئىشلەتسە چاچ تېخىمۇ يۇمشاق بولىدۇ.","nemlendürüsh chach sütini ishletse chach téximu yumshaq bolidu."]],"灌水":[["夏季需要给农作物充分灌水。","يازدا يېزا ئىگىلىك زىرائەتلىرىگە يېتەرلىك سۇ بېرىش كېرەك.","yazda yéza igilik ziraetlirige yéterlik su bérish kérek."]],"火钳":[["用火钳夹住烧红的铁块。","قىزىپ تۇرغان تۆمۈر پارچىسىنى ئوت قىسقۇچ بىلەن قىسىۋال.","qizip turghan tömür parchisini ot qisquch bilen qisiwal."]],"火石":[["用火石擦火，就能点燃干柴。","چاقماق تېشى بىلەن ئوت چاقسا، قۇرۇق ياغاچنى تۇتاشتۇرغىلى بولىدۇ.","chaqmaq téshi bilen ot chaqsa, quruq yaghachni tutashturghili bolidu."]],"灰颈鹀":[["灰颈鹀的颈部有明显的灰斑。","كۈلرەڭ بوينى سېرىقچى قۇشنىڭ بوينىدا ئېنىق كۈلرەڭ داغ بار.","külreng boyni sériqchi qushning boynida éniq külreng dagh bar."]],"炸土豆片":[["炸土豆片金黄酥脆。","پىشۇرۇلغان كارتوشكا پارچىلىرى ئالتۇن رەڭدە قىتىراپ تۇرىدۇ.","pishurulghan kartoshka parchiliri altun rengde qitirap turidu."]],"乌兰察布":[["乌兰察布是内蒙古自治区的一个盟。","ئۇلانچابۇ ئىچكى موڭغۇل ئاپتونوم رايونىدىكى بىر ئايماقتۇر.","ulanchabu ichki mongghul aptonom rayonidiki bir aymaqtur."]],"烽烟四起，战火纷飞":[["烽烟四起，战火纷飞，百姓流离失所。","ئوت سىگنالى تۆت تەرەپكە تارقاپ، ئۇرۇش ئوتى ئەۋج ئېلىپ، خەلق ئۆي-جايىدىن ئايرىلىپ قالدى.","ot signali töt terepke tarqap, urush oti ewj élip, xelq öy-jayidin ayrilip qaldi."]],"煽情":[["他的演讲总是充满煽情的话语。","ئۇنىڭ سۆزى ھەمىشە ھېسسىياتقا تولغان سۆزلەرگە تولىدۇ.","uning sözi hemishe héssiyatqa tolghan sözlerge tolidu."]],"熊耳山":[["熊耳山以其独特的山形而闻名。","ئېيىق قۇلاق تېغى ئۆزىگە خاس تاغ شەكلى بىلەن داڭلىق.","éyiq qulaq téghi özige xas tagh shekli bilen dangliq."]],"烟火气":[["这碗面带着浓郁的烟火气，格外美味。","بۇ بىر چىنە ئۇگرا قويۇق ئوت-تۈتەك ھىدىگە ئىگە بولۇپ، ئالاھىدە تەملىك.","bu bir chine ugra qoyuq ot-tütek hidige ige bolup, alahide temlik."]],"烫平":[["用熨斗把衣服烫平。","كىيىمنى دەملەك بىلەن تۈزلىتىڭ.","kiyimni demlek bilen tüzliting."]],"烧高香":[["能烧高香真是幸运。","بەختلىك ئىشكى، خۇشپۇراق تۈتەك يېقىش.","bextlik ishki, xushpuraq tütek yéqish."]],"燕窝":[["燕窝是珍贵的食材。","قارلىغاچ ئۇۋىسى قىممەتلىك يېمەكلىك ماددىسىدۇر.","qarlighach uwisi qimmetlik yémeklik maddisidur."]],"特卫强":[["特卫强是知名安保公司。","تىۋېك بىخەتەرلىك ساھەسىدىكى تونۇلغان شىركەت.","tiwék bixeterlik sahesidiki tonulghan shirket."]],"玉树":[["这里的风景如玉树般美丽。","بۇ يەرنىڭ مەنزىرىسى يۈشۈ دەرىخىدەك گۈزەل.","bu yerning menzirisi yüshü derixidek güzel."]],"兽力车":[["兽力车依靠动物拉行。","ھايۋان كۈچى ئارابىسى ھايۋانلارغا تارتىپ ماڭىدۇ.","haywan küchi arabisi haywanlargha tartip mangidu."]],"猛劲儿":[["他干起活来真有猛劲儿。","ئۇ ئىشلەشكە كەلگەندە ھەقىقەتەن كۈچلۈك ئىھتىياجلىق.","u ishleshke kelgende heqiqeten küchlük ihtiyajliq."]],"王洪文":[["王洪文曾是重要领导人。","ۋاڭ خۇڭۋېن ئىلگىرى مۇھىم رەھبەر ئىدى.","wang xungwén ilgiri muhim rehber idi."]],"玉红省":[["玉红省位于中国西南部。","يۈخۇڭ ئۆلكىسى جۇڭگونىڭ جەنۇبىي غەربىدە جايلاشقان.","yüxung ölkisi junggoning jenubiy gherbide jaylashqan."]],"瓯海":[["瓯海是浙江省的一个著名地区。","ئوخەي جېجياڭ ئۆلكىسىنىڭ بىر مەشھۇر رايونىدۇر.","oxey jéjyang ölkisining bir meshhur rayonidur."]],"瓮声瓮气":[["他的声音瓮声瓮气，听起来很沉闷。","ئۇنىڭ ئاۋازى غۇڭۇلداپ چىقىدۇ، ئاڭلىشىشىغا ئىنتايىن غۇۋا.","uning awazi ghunguldap chiqidu, anglishishigha intayin ghuwa."]],"男傧相":[["男傧相在婚礼上笑容满面。","ئەر كۈيئوغۇل توي مۇراسىمىدا چىرايىدىن كۈلۈمسىرەپ تۇردى.","er küy'oghul toy murasimida chirayidin külümsirep turdi."]],"甲酚":[["甲酚具有杀菌消毒作用。","جيافېن باكتېرىيە ئۆلتۈرۈش ۋە دېزىنفېكسىيەلەش رولىغا ئىگە.","jyafén baktériye öltürüsh we dézinféksiyelesh roligha ige."]],"甲醚":[["甲醚是一种常用的有机溶剂。","جييامىي بىر خىل كۆپ ئىشلىتىلىدىغان ئورگانىك ئېرىتكۈچ.","jyyamiy bir xil köp ishlitilidighan organik éritküch."]],"留校":[["他被学校留校继续学习。","ئۇ مەكتەپتە قالدۇرۇلۇپ ئوقۇشىنى داۋاملاشتۇردى.","u mektepte qaldurulup oqushini dawamlashturdi."]],"用餐":[["我们准备开始用餐了。","بىز تاماق يېيىشكە تەييارلىق قىلىۋاتىمىز.","biz tamaq yéyishke teyyarliq qiliwatimiz."]],"番椒":[["番椒的辛辣味道让人食欲大增。","قىزىل مۇچنىڭ ئاچچىق تەمى كىشىنىڭ ئىشتىھاسىنى زور دەرىجىدە ئاشۇرىدۇ.","qizil muchning achchiq temi kishining ishtihasini zor derijide ashuridu."]],"病重":[["他的病情突然病重。","ئۇنىڭ كېسەللىك ئەھۋالى تۇيۇقسىز ئېغىرلاشتى.","uning késellik ehwali tuyuqsiz éghirlashti."]],"白头到老":[["夫妻二人决定白头到老。","ئەر-خوتۇن ئىككىسى ئاق ساقال بولغۇچە بىللە ياشاشنى قارار قىلدى.","er-xotun ikkisi aq saqal bolghuche bille yashashni qarar qildi."]],"白颈鹳":[["白颈鹳常在田野中活动。","ئاق بوينلۇق لەيلەك دائىم ئېتىزلىقلاردا پائالىيەت قىلىدۇ.","aq boynluq leylek daim étizliqlarda paaliyet qilidu."]],"硫酸铵":[["硫酸铵是常用的氮肥。","سۇلفات ئاممونىي ئادەتتە ئىشلىتىلىدىغان ئازوت ئوغۇتى.","sulfat ammoniy adette ishlitilidighan azot oghuti."]],"磷矿":[["磷矿是重要的非金属矿产资源。","فوسفور كانى مۇھىم مېتال ئەمەس مىنېرال بايلىق.","fosfor kani muhim métal emes minéral bayliq."]],"社会阶层":[["不同社会阶层的差异日益明显。","تۈرلۈك ئىجتىمائىي قاتلاملار ئارىسىدىكى پەرق كۈنسېرى ئېنىقلىشىۋاتىدۇ.","türlük ijtimaiy qatlamlar arisidiki perq künséri éniqlishiwatidu."]],"石库门":[["石库门是上海特有的传统建筑。","شىكۇمېن شاڭخەيگە خاس ئەنئەنىۋى بىنا.","shikumén shangxeyge xas en'eniwi bina."]],"穿过":[["汽车穿过繁忙的街道。","ماشىنا ئالدىراش كوچىدىن سىڭىپ ئۆتتى.","mashina aldirash kochidin singip ötti."]],"笑料":[["这个节目充满了笑料。","بۇ پروگرامما كۈلكىلىك ئىشلارغا تولغان.","bu programma külkilik ishlargha tolghan."]],"细颗粒物":[["细颗粒物是空气污染的主要来源之一。","ئىنچىكە زەررىچىلەر ھاۋا بۇلغىنىشىنىڭ ئاساسلىق مەنبەلىرىنىڭ بىرى.","inchike zerrichiler hawa bulghinishining asasliq menbelirining biri."]],"给你点颜色看看":[["他故意给你点颜色看看。","ئۇ سىزگە قەستەن ئازار بېرىپ باقماقچى.","u sizge qesten azar bérip baqmaqchi."]]};
